(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0012.js"] = [{"id":"glyph-kai-8f83","script":"kai","character":"较","reading":"jiào","description":"车箱\n概略;大旨\n较 〈动〉\n较量\n⒈比，比较～量。论才～智。〈引〉相比显得更进一层～佳。～好。～大的成绩。\n⒉明显～然著明。\n⒊大概大略此其大～也。\n较jué 1.车箱两旁板上的横木。 2.指车厢。 3.直。 4.谓专略其利。参见\"较固\"。 5.法。 6.通\"角\"。竞逐。\n较xiào 1.学校。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-较"},{"id":"glyph-kai-8f85","script":"kai","character":"辅","reading":"fǔ","description":"助手\n面颊\n⒈车轮外的两个直条，用以增强车辐的承载力。〈引〉帮助，协助～助。～导有方。相～相成。\n【辅音】 也叫\"子音\"。发音时，从肺里出来的气，经口腔或鼻腔受到障碍所成的音。拼音字母b、c、d、g等都是辅音。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辅"},{"id":"glyph-kai-8f86","script":"kai","character":"辆","reading":"liàng","description":"用于车,指单个数\n指鞋一双","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辆"},{"id":"glyph-kai-8f88","script":"kai","character":"辈","reading":"bèi","description":"也指车列,车队\n世;辈分\n某类人\n群,队\n①行辈；辈分老一～。\n③一世；一生一～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辈"},{"id":"glyph-kai-8f89","script":"kai","character":"辉","reading":"huī","description":"晨光\n产生光彩;照耀\n⒈闪耀的光彩光～。彩霞余～＄霓扬～。\n⒉照耀～映。星月交～。\n辉yùn 1.日月周围的光气。\n辉hún 1.赤色。参见\"辉辉\"。\n辉xūn 1.熏灼。\n辉xuàn 1.古代制造皮鼓之吏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辉"},{"id":"glyph-kai-8f90","script":"kai","character":"辐","reading":"fú","description":"聚集如辐\n⒈车轮上一条一条的直条，从轮边连结到轮的中心。\n【辐射】光、热、电波等向四周发散的现象。\n【辐辏】\n【辐凑】车辐会聚于车轮的中心。〈喻〉人或物的聚集四方～辏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辐"},{"id":"glyph-kai-8f91","script":"kai","character":"辑","reading":"jí","description":"整套书籍、资料等按内容或发表先后次序分成的各个部分\n聚集\n敛,拖着不使脱落\n把各种来源的书面材料或项目经加工汇编成一个文件或\n⒈〈古〉车厢。泛指车子。\n⒉聚集甲～而兵聚。特指编书报等或编成的书编～。丛书第四～。\n⒊和睦～睦。〈引〉安抚，安定以～一方。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辑"},{"id":"glyph-kai-8f93","script":"kai","character":"输","reading":"shū","description":"交出;缴纳\n已乃劝输巨室,令\n⒈运送，注入运～。～入。～血。\n⒉送给，捐献～财。捐～。\n⒊负，败～了两盘棋。\n输shù 1.经穴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-输"},{"id":"glyph-kai-8f96","script":"kai","character":"辖","reading":"xiá","description":"侍卫\n管辖\n卡,夹\n⒈车上的部件，用于挡住车轮，不使脱落车～。\n⒉管理统～。直～市。\n辖hé 1.见\"輵辖\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辖"},{"id":"glyph-kai-8f97","script":"kai","character":"辗","reading":"niǎn；zhan","description":"通碾”。磙压;碾压\n辗转,也作展转”\n转;回转\n①翻来覆去地转动～转反侧。忧心～转。\n②经过许多曲折～转传诵。\n辗niǎn 1.石碾。 2.谓把糙米加工成熟米的碾轧过程。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辗"},{"id":"glyph-kai-8f99","script":"kai","character":"辙","reading":"zhé","description":"车子\n道路\n途径;门路;路数,路子\n比喻错误或教训\n⒈车轮碾压出的痕迹车～。如出一～。〈引〉车行的路线顺～行。莫抢～儿。又〈引〉杂曲、戏曲、歌词等所押的韵这段戏词合～。\n⒉〈方〉办法有～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辙"},{"id":"glyph-kai-8f9b","script":"kai","character":"辛","reading":"xīn","description":"xīn：(1)辣～辣。五～。\n(2)劳苦，艰难～苦。～劳。\n(3)悲伤～酸。\n(4)天干的第八位，用于作顺序第八的代称～亥革命。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辛"},{"id":"glyph-kai-8f9c","script":"kai","character":"辜","reading":"gū","description":"gū：(1)罪无～。～功（罪行）。死有余～。\n(2)负，背～负。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辜"},{"id":"glyph-kai-8f9e","script":"kai","character":"辞","reading":"cí","description":"口供\n①优美的语言；言词～藻、修～。\n②古典文学的一种体裁～赋、楚～。\n④告别；告辞～行。\n⑤辞职。\n⑥辞退解雇。\n⑦躲避；推托推～、不～劳苦。\n【辞呈】向上级请求辞职的呈文。\n文手法，与辞已不相同。\n【辞格】积极修辞的各种格式。如比喻、借代。又称修辞格。\n【辞海】\n①书名。陆费逵等编。1936年中华书局初版。为综合性大型词典。收单字13000多，词语77000条左右，兼有字典和词典性质，通称旧辞海。\n②书名。辞海编辑委员会编。1965年出版未定稿，1979年出版三卷本，1980年出版缩印本。收单字14872个，词目91706条，内容包括成语、典故、人物、著作、历史事件以及\n各学科名词术语等。为常用的语文工具书。通称新辞海。1989年修订后再版。\n【辞令】社交场合应对得体的话语外交～、善于～。又作词令。\n【辞书】字典、辞典、百科全书、专科辞典的统称。\n【辞源】\n①书名。陆尔奎等1908年编纂。1915年商务印书馆出版，为中国现代第一部综合性辞典，通称旧辞源。\n②书名。1979年出版。主要作为阅读古籍用的工具书和古典文史研究工作者的参考书。全书共收单字12890个，词语84134条，收词范围一般到鸦片战争为止。内容以旧有辞书","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辞"},{"id":"glyph-kai-8f9f","script":"kai","character":"辟","reading":"pì；bì","description":"bì：(1)君主复～。\n(2)指君主招来，授予官职～召。～引。～书。～除（征召推举授官）。～举。\n(3)古同避”，躲，设法躲开。\n(4)古同睥”，睥睨。\n（①～③陃）\npì：(1)开发建设开～。\n(2)驳斥，排除～邪。～谣。～蠹。\n(3)透彻精～。透～。鞭～入里。\n(4)法，刑大～（古代指死刑）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辟"},{"id":"glyph-kai-8fa3","script":"kai","character":"辣","reading":"là","description":"là：(1)像姜、蒜等的剌激性味道～椒（一年生草木植物，果实有毛笔尖形、灯笼形等，青色，成熟后变成红色。可食，亦可入药。亦称辣子”）。辛～。～乎乎。酸甜苦～。\n(2)辣味刺激～眼睛。\n(3)凶狠，刻毒毒～。泼～。手段～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辣"},{"id":"glyph-kai-8fa8","script":"kai","character":"辨","reading":"biàn","description":"biàn：(1)分别，分析，明察～别。～认。～析。～正。～识。明～是非。\n(2)古代土地面积单位，九夫为一辨，七辨为一并。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辨"},{"id":"glyph-kai-8fa9","script":"kai","character":"辩","reading":"biàn","description":"分别,辨别。通辨”\n辩 biàn辩解；争论争～。\n【辩白】说明事实或理由，用来消除误会或受到的指责。又作辨白。\n【辩驳】提出理由或根据来驳斥和否定对方的意见无可～。\n【辩才】辩论的才干。\n【辩护】在刑事诉讼中，被告人及其辩护人，针对控告所进行的申辩话动。\n【辩护人】在刑事案件中，受被告人委托或由法院指定，在法庭上为被告申辩的人。他能向法院提供证明被告人无罪、罪轻的材料和提出减轻、免除其刑事责任的意见。我\n国刑事诉讼法规定，能充当辩护人的有律师、人民团体或被告人所在单位推荐的，或经人民法院许可的公民、被告人的近亲属或监护人。\n【辩论】双方用一定的理由来说明自己的见解，否认或修正对方的意见，以便最后得到正确的认识或共同的意见～会。\n【辩难】辩驳或用难以回答的问题质问对方互相～。\n【辩诬】对错误的指责进行辩解。\n【辩正】辩明是非，纠正错误。又作辨证。\n【辩证】\n①分析考证。又作辨证。\n②合乎辩证法的～的统一。\n【辩证法】\n①关于事物矛盾的运动、发展和变化的一般规律的哲学学说。它是和形而上学相对立的世界观和方法论。认为事物处在不断运动、变化和发展之中，是由于事物内部的矛盾斗争\n所引起的。\n②特指唯物辩证法。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辩"},{"id":"glyph-kai-8fab","script":"kai","character":"辫","reading":"biàn","description":"交织,编结。也作编”\n发辫。分股编紧的头发\n像辫子一样的条状物\n①辫子。把头发分股交叉编成的条条梳小～。\n②指像辫子的东西蒜～子。\n【辫子军】对张勋所属军队的通称。武昌起义后，江南提督张勋率部继续效忠清王朝，禁止部下剪辫子，被称为'辫子军'。在张勋率领下，于1917年6月进驻北京，企图复辟帝\n制。在全国人民强烈的反对下，复辟闹剧仅仅10天便告失败。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辫"},{"id":"glyph-kai-8fb0","script":"kai","character":"辰","reading":"chén","description":"chén：(1)地支的第五位，属龙。\n(2)用于记时～时（上午七点至九点）。\n(3)时日～光。时～。诞～。\n(4)日、月、星的总称北～（北极星）。星～。\n(5)古同晨”，清早。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辰"},{"id":"glyph-kai-8fb1","script":"kai","character":"辱","reading":"rǔ","description":"rǔ：(1)羞耻羞～。耻～。\n(2)使受到羞耻～骂。侮～。折～。\n(3)谦辞，表示承蒙～承。～赐。\n(4)玷污，辜负～没（mò）。～命。玷～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辱"},{"id":"glyph-kai-8fb9","script":"kai","character":"边","reading":"biān","description":"边境\n①物体周围的部分海～。\n②界限～界、～防。\n③表示地位、方向东～、上～。\n④两个'边'连用，表示动作同时进行～学～用。\n⑤几何图形上夹成角的射线或围成多角形的线段。\n⑥姓。\n【边鄙】边远的地方。\n【边币】中国抗日战争时期，陕甘宁边区银行、晋察冀边区银行、豫鄂边区建设银行等发行的货币。\n【边边边定理】有3边对应相等的两个三角形全等，简写为边边边或sss。\n【边陲】边境；边疆西北～。\n【边关】边境上的关口。\n【边角边定理】两个三角形的两组对应边和它们的夹角对应相等，那么两个三角形全等，简写成边角边或sas。\n【边款】刻于印侧的题记。包括年、月，名款、诗文、图案等。\n【边塞】边境的要塞。\n【边饰纹样】装饰于器物边缘的纹样。在服装、书籍封面和商品包装上常应用这种装饰。又称边缘纹样。民间称花边。\n【边心距】正多边形的中心到它的一边的距离叫做正多边形的边心距。正多边形的边心距等于正多边形的内切圆半径r。\n【边缘海】位于大陆的边缘，一侧以大陆为界，另一侧以半岛、岛屿或岛弧与大洋分隔，水流交换通畅。如我国的黄海、东海、南海。又称陆缘海。\n【边缘科学】\n①以学科间有关的共同问题为研究对象，运用多学科的理论和方法探讨解决问题的途径以促进科学全面、深入发展的新兴学科。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-边"},{"id":"glyph-kai-8fbd","script":"kai","character":"辽","reading":"liáo","description":"开阔\n久远","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-辽"},{"id":"glyph-kai-8fbe","script":"kai","character":"达","reading":"dá","description":"到达；通畅；表达、传达；通晓事理。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-8fc1","script":"kai","character":"迁","reading":"qiān","description":"晋升或调动\n⒈搬移，换地点～移。～徙。～都。～厂。搬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迁"},{"id":"glyph-kai-8fc2","script":"kai","character":"迂","reading":"yū","description":"yū：(1)曲折，绕远～回。～缓（行动迟缓）。\n(2)言行或见解陈旧不合时宜～论。～气。～儒。～阔（不切合实际）。～腐（说话、行事拘泥于陈旧的准则，不适应新时代）。～夫子（迂腐的读书人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迂"},{"id":"glyph-kai-8fc4","script":"kai","character":"迄","reading":"qì","description":"qì：(1)到，至起～。～今。\n(2)始终（用于未”或无”前）～未成功。～无音信。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迄"},{"id":"glyph-kai-8fc5","script":"kai","character":"迅","reading":"xùn","description":"xùn：快～速。～即。～疾。～捷。～猛。～雷不及掩耳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迅"},{"id":"glyph-kai-8fc7","script":"kai","character":"过","reading":"guò","description":"古国名\n姓,过国之后\n⒈经历，经历某个空间、时间、地点～去。经～。走～。度～。～节。～桥。～河。\n⒉进行某种处理～磅。～滤。～目。\n⒊超越，超出某种范围或限度胜～。太～分。莫～火。～于激动。刚刚～期。已～半数。\n⒋转移，传递，交往～户。～电。～从。\n⒌错误～失。～错。知～必改。\n⒍用在动词后面。\n①助词。〈表〉曾经或完毕看见～。去～了。曾用～。吃～了。\n②与\"来\"、\"去\"连用，〈表〉趋向搬～来。走～去。\n①花费太多。\n②辜负。\n过huò 1.车的盛膏器。 2.通\"祸\"。灾祸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-过"},{"id":"glyph-kai-8fc8","script":"kai","character":"迈","reading":"mài","description":"行走;跨步\n超过,跨越\n时光流逝\n⒈行，去长～。\n⒉跨步向前～进。\n⒊超过，超越三王可～。五帝可越。\n⒋老年～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迈"},{"id":"glyph-kai-8fce","script":"kai","character":"迎","reading":"yíng","description":"yíng：(1)接～接。欢～。～宾。～候。\n(2)面对着，冲着～面。～风（ａ．对着风；ｂ．随风）。～刃而解（jiě）。\n(3)揣度别人心意而投其所好逢～。～合。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迎"},{"id":"glyph-kai-8fd0","script":"kai","character":"运","reading":"yùn","description":"搬运;运输\n将运舟而\n⒈转动，移动～转。～行。\n⒉输送，搬送～输。搬～。空～。～。\n⒊使用，应用，谋划～笔。～用。～筹帷幄。\n⒋迷信者所谓\"命中注定的遭遇\"相信～气、命～者愚昧。\n①人工开挖的水道。\n②特指我国的大运河，从北京到杭州，全长1794公里。\n①物理学上指物体位置不断变移的现象。\n②哲学上指物质存在的形式和根本属性。包括宇宙中所发生的一切变化和过程，宇宙中的各种现象都是物质运动的表现形式。\n③锻炼身体，增强体质的活动体育～动。\n④有组织、有计划、有目的的群众性活动五四～动。\n⑤为达到某种目的而进行的钻营奔走到处～动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-运"},{"id":"glyph-kai-8fd1","script":"kai","character":"近","reading":"jìn","description":"jìn：(1)距离短，与远”相对接～。附～。靠～。～路。～景。舍～求远。～在眉睫。～朱者赤，～墨者黑。～水楼台。\n(2)现在以前不久的时间～况。～来。～代。～岁。～闻。～照。～体诗。\n(3)亲密亲～。～亲。～臣。平易～人。\n(4)差别小，差不多接～。相～。\n(5)浅显言～旨远。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-近"},{"id":"glyph-kai-8fd4","script":"kai","character":"返","reading":"fǎn","description":"fǎn：回，归往～。～航。～工。～青（某些植物的幼苗移栽或越冬后，由黄转绿并恢复生长）。～销。～修。～还（huán）。流连忘～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-返"},{"id":"glyph-kai-8fd8","script":"kai","character":"还","reading":"hái；huán","description":"hái：仍然，再，又；尚且。huán：返回；归还；恢复原状。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-8fd9","script":"kai","character":"这","reading":"zhè","description":"此,指目前的或较近的或刚刚提到的人、物、事或想法\n此刻,现在\n⒈\"这zhè、一\"的合音，在指数量时不限于一～种。～些。～月。～五年。\n⒈指示代词。此，跟\"那\"相对，指较近的人、物、事、时间、地点等～人。～些。～事。～时。～地方。\n这yàn 1.迎接，迎讶。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-这"},{"id":"glyph-kai-8fdb","script":"kai","character":"进","reading":"jìn","description":"水陆并进。\n⒈向前，跟\"退\"相对跃～。向前～。勇者不得独～。\n⒉入，到里面去～门。～厂。～中学。\n⒊收入或买入～钱。～衣服。\n⒋向上移动更～一层楼。\n⒌送上，奉呈～献。～酒。～言。～谏。\n⒍推荐，吸取荐～。引～。吸～。\n⒎旧时房院前后的层次，每一个院叫\"一进\"这座房屋是三～院子。\n①向前发展，比原来好他已有很大的～步。\n②适应时代的要求，对社会发展起促进作用的～步思想。\n⒈闭口，不说话～若寒蝉。〈引〉关闭～门。\n⒉因寒冷而哆嗦打寒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-进"},{"id":"glyph-kai-8fdc","script":"kai","character":"远","reading":"yuǎn","description":"⒈空间或时间的距离长，跟\"近\"相对～方。～古。路～。长～。久～。\n⒉不接近，关系疏～亲。疏～。\n远yuàn 1.离开;避开。 2.不亲近;不接近。 3.违背。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-远"},{"id":"glyph-kai-8fdd","script":"kai","character":"违","reading":"wéi","description":"避开\n⒈背，反，不遵守～背。～反。～犯。～法。不～农时。\n⒉离别，不见面久～了。\n⒊〈古〉避开以～其害。\n违huí 1.掉转。 2.返回。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-违"},{"id":"glyph-kai-8fde","script":"kai","character":"连","reading":"lián","description":"姻亲关系\n⒉联合外～友邦。\n⒊带，加上～说带拉。～根拔掉。～他俩总共四人。\n⒌军队编制单位，是\"营\"的下一级，\"排\"的上一级。\n连liǎn 1.艰难。\n连làn 1.见\"连石\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-连"},{"id":"glyph-kai-8fdf","script":"kai","character":"迟","reading":"chí","description":"迟钝;反应慢,不灵敏\n迟疑;犹豫\n寻声暗问弹者谁,琵琶声\n①缓慢行动～缓。\n②比规定或合适的时间靠后推～、～到早退。\n③姓。\n【迟暮】指人的晚年。\n【迟效肥料】所含养分必须经过微生物分解转化才能被植物吸收利用的肥料。其见效迟缓而后效长，适于作基肥。包括大部分有机肥料及溶解度小的无机肥料。\n【迟疑】拿不定主意～不决。\n⒈缓慢～缓。～ ～不走。\n⒉晚～到。～熟。\n⒊不灵敏～钝。\n⒋长久～久而不相及。\n①早晚。\n②或早或晚。\n迟zhì 1.等待。 2.比及，等到。 3.想望，希望。 4.接待，招待。 5.副词。乃。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迟"},{"id":"glyph-kai-8fe2","script":"kai","character":"迢","reading":"tiáo","description":"tiáo：远，高远的样子～远。～递。千里～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迢"},{"id":"glyph-kai-8fea","script":"kai","character":"迪","reading":"dí","description":"dí：(1)开导启～。\n(2)进弗求弗～。\n(3)继承汉～于秦，有因有革。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迪"},{"id":"glyph-kai-8feb","script":"kai","character":"迫","reading":"pò；pǎi","description":"pò：(1)用强力压制，硬逼逼～。～害。压～。强～。胁～。～降（jiàng）。～降（xiáng）。～不得已。\n(2)接近～近。～冬。\n(3)急促急～。～切。～不及待。\n(4)狭窄地势局～。\npǎi：〔～击炮〕一种火炮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迫"},{"id":"glyph-kai-8fed","script":"kai","character":"迭","reading":"dié","description":"dié：(1)交换，轮流交～。更～。～为宾主。～相为用。\n(2)屡次，连着～连。～忙。高潮～起。\n(3)及忙不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迭"},{"id":"glyph-kai-8ff0","script":"kai","character":"述","reading":"shù","description":"shù：(1)讲话，陈说，叙～。～评。描～。论～。综～。～职。～而不作。\n(2)修纂著～。\n(3)循，顺行报我不～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-述"},{"id":"glyph-kai-8ff7","script":"kai","character":"迷","reading":"mí","description":"mí：(1)分辨不清，失去了辨别、判断的能力～信。～糊。～津。～惘。～蒙（ａ．昏暗看不清；ｂ．神志凝不清；ｅ．使迷惑，受蒙蔽）。执～不悟。\n(2)醉心于某种事物，发生特殊的爱好～恋。入～。\n(3)沉醉于某种事物的人棋～。革新～。\n(4)使人陶醉景色～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迷"},{"id":"glyph-kai-8ff9","script":"kai","character":"迹","reading":"jì","description":"jì：(1)脚印踪～。足～。血～。笔～。\n(2)物体遗留下的印痕印～。\n(3)前人遗留下的事物古～。实～。\n(4)追寻踪迹汉求将军急，～且至臣家”。\n(5)据实迹考知～汉功臣，亦皆割符世爵”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-迹"},{"id":"glyph-kai-8ffd","script":"kai","character":"追","reading":"zhuī；duī","description":"zhuī：(1)赶，紧跟着～逐。～逼。～随。～光。～剿。～捕。～奔逐北。\n(2)回溯过去，补做过去的事～溯。～悼。～加。～认。\n(3)竭力探求，寻求～问。～寻。～究。～索。\n逃；\nduī：(1)雕琢～琢（雕刻）。\n(2)古代乐器钟上用以悬挂的钮眼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-追"},{"id":"glyph-kai-9000","script":"kai","character":"退","reading":"tuì","description":"tuì：(1)向后移动，与进”相对～步。～路。～却。～让。倒～。\n(2)离开，辞去～席。～伍。～职。～休。引～。\n(3)送还，不接受，撤销～还。\n(4)脱落～色。～毛。减～。\n(5)和柔的样子～然。\n(6)迟缓，畏缩求也～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-退"},{"id":"glyph-kai-9001","script":"kai","character":"送","reading":"sòng","description":"sòng：(1)把东西从甲地运到乙地～信。～审。输～。护～。呈～。\n(2)赠给～礼。赠～。雪中～炭。\n(3)陪伴人到某一地点欢～。～别。～亲。\n(4)丢掉断～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-送"},{"id":"glyph-kai-9002","script":"kai","character":"适","reading":"shì","description":"⒈相合，妥当，切合～合。～宜。～当。～龄。～度。～中。正好～用。\n⒉恰好，正巧～得其反。～逢其会。～销对路。\n⒊才，刚才～从何地来？\n⒋舒服她身体不～。\n⒌往，去～长沙。无所～从。\n⒍旧称女子嫁人～人。\n⒈〈古〉疾速。多见于人名。\n适dí 1.专主，作主。 2.同\"嫡\"。正妻称\"嫡妻\"，正妻所生之子称\"嫡子\"。 3.指正统，正宗。 4.亲厚。 5.通\"谛\"。注意，仔细。 6.通\"的\"。指的，对象。 7.通\"\n的\"。清楚，分明。\n适tì 1.见\"适适\"。\n适zhé 1.责备，谴责。 2.责罚，惩罚。 3.贬谪。 4.毛病;过失。 5.旧指天象变异。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-适"},{"id":"glyph-kai-9003","script":"kai","character":"逃","reading":"táo","description":"táo：(1)为躲避不利于自己的环境或事物而离开～跑。～敌。～匿。～遁。～逸。\n(2)躲开不愿意或不敢接触的事物～避。～难（nàn）。～汇。～税。～世（避世）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逃"},{"id":"glyph-kai-9006","script":"kai","character":"逆","reading":"nì","description":"nì：(1)方向相反，与顺”相对～流。～行。～风。～转（zhuǎn）（局势恶化）。莫～之交。\n(2)抵触，不顺从忤～。忠言～耳。\n(3)背叛，背叛者或背叛者的叛～。～产。\n(4)迎接～旅（旅店）。\n(5)预先～料（预料）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逆"},{"id":"glyph-kai-9009","script":"kai","character":"选","reading":"xuǎn","description":"假借为柬”。挑选,选择\n⒈择，挑拣～择。～派。挑～。\n⒉被选中了的人～。入～。已～上。\n⒊被选出汇编成册的作品～集。诗～。民歌～。\n①〈古〉通过推举或科举盐官吏的制度。\n选suàn 1.数词。万。 2.一说十秭为选。 3.通\"算\"。数;计算。\n选shuā 1.古钱币单位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-选"},{"id":"glyph-kai-900a","script":"kai","character":"逊","reading":"xùn","description":"辞让;退让\n不如,比不上\n⒈让，退让唐尧～位。\n⒉谦让，恭顺谦～。傲慢不～。\n⒊逃远～。～于外。\n⒋差，次～色。略～一筹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逊"},{"id":"glyph-kai-900f","script":"kai","character":"透","reading":"tòu","description":"tòu：(1)通过，穿通～明。～镜。～视。～析。渗～。穿～。\n(2)通达～彻。～辟。\n(3)泄露～露。\n(4)极度恨～了。\n(5)显露这朵花白里～红。\n(6)达到饱满、充分的程度雨下～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-透"},{"id":"glyph-kai-9010","script":"kai","character":"逐","reading":"zhú","description":"zhú：(1)强迫离开～客令。放～。驱～。\n(2)依照先后次序，一一挨着～步。～个。～渐。～年。～一。\n(3)追赶～鹿（喻争夺天下）。角（jué）～（争相取胜）。追～。笑～颜开。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逐"},{"id":"glyph-kai-9012","script":"kai","character":"递","reading":"dì","description":"传;传送\n①传送；传递；投～、～眼色。\n②顺次～补、～增。\n【递补】顺次补充。\n【递减】一次比一次减少。\n【递减数列】从第二项起，每一项都小于它的前面一项的数列。称递减数列。如1，1/2，1/3，…，1/n，…。其中，n是自然数。\n【递进复句】由两个有递进关系的分句组成的句子，后一分句表示的意思比前一分句更进一层。如'他不但会干，而且干得很好'。\n【递进句群】表示递进关系的句群。它与递进复句相同的是都表示递进关系，而不同的是它的前一分句或后一分句不是单句，而是由一组单句紧密结合起来表达一个中心意思的\n句群。\n【递推公式】通过初始的条件，可以初步推出所需要的结论的公式。\n【递增数列】从第二项起，每一项都大于它的前面一项的数列。如1，2，3，…，n，…。又称上升数列。\n【递质】〈医〉指神经末梢兴奋时释放的某种特殊化学物质。它可以使效应器官发生反应，如腺体分泌，也可以使突触后神经原兴奋或抑制。如乙酰胆碱。又称介质。\n递shì 1.通\"适\"。适宜。 2.通\"逝\"。往;去。\n递dài 1.围绕。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-递"},{"id":"glyph-kai-9014","script":"kai","character":"途","reading":"tú","description":"tú：道路路～。～径。旅～。长～。坦～。日暮～穷。前～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-途"},{"id":"glyph-kai-9017","script":"kai","character":"逗","reading":"dòu","description":"dòu：(1)停留～留。～号。\n(2)引，惹弄～哏。～引。～人。～笑儿。\n(3)同读2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逗"},{"id":"glyph-kai-901a","script":"kai","character":"通","reading":"tōng","description":"tōng：(1)设有阻碍，可以穿过，能够达到～风。～天。～气。～宵。～行。～过。～衢。贯～。四～八达。曲径～幽。\n(2)懂得，彻底明了～晓。～彻。～今博古。～情达理。\n(3)传达～令。～讯。～报。～告。～知。～缉。～谍。\n(4)往来交接～敌。～商。～邮。～融。～假（jiǎ）（汉字的通用和假借）。串～。沟～。\n(5)普遍、全～才（指知识广博，具有多种才能的人）。～论。～体。～身。～读。～常。～病。～盘。普～。\n(6)男女不正当的性行为～奸。私～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-通"},{"id":"glyph-kai-901b","script":"kai","character":"逛","reading":"guàng","description":"guàng：闲游，游览游～。闲～。～街。～灯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逛"},{"id":"glyph-kai-901d","script":"kai","character":"逝","reading":"shì","description":"shì：(1)过去，往～去。～川（逝去的流水，喻过去了的岁月或事物）。光阴易～。子在川上曰～者如斯夫！”\n(2)死，多用于对死者的敬意～世。长～。仙～。\n(3)古同誓”，表决心之词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逝"},{"id":"glyph-kai-901e","script":"kai","character":"逞","reading":"chěng","description":"chěng：(1)显示，施展，炫耀，卖弄～能。～强。～凶。～威风。\n(2)意愿实现，称心～志。～吾愿。不～之徒（因私欲得不到满足而为非作歹，捣乱闹事的人）。\n(3)放任～性。骄～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逞"},{"id":"glyph-kai-901f","script":"kai","character":"速","reading":"sù","description":"sù：(1)快～记。～效。～印。～写。～成。飞～。神～。\n(2)速度慢～。超～。加～。风～。\n(3)邀请，招致不～之客。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-速"},{"id":"glyph-kai-9020","script":"kai","character":"造","reading":"zào","description":"zào：(1)制作，做制～。创～。～物。～反。～孽。建～。～表。～册。～价。～型。粗制滥～。\n(2)瞎编胡编乱～。捏～。\n(3)成就～诣。\n(4)培养～就。\n(5)相对两方面的人，法院里指诉讼的两方。即原告和被告两～。甲～。乙～。\n(6)到，去～访。\n(7)稻子等作物从播种到收割的次数一年两～。晚～。\n(8)时代，年代末～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-造"},{"id":"glyph-kai-9022","script":"kai","character":"逢","reading":"féng","description":"féng：(1)遇到～遇。久别重～。～凶化吉。狭路相～。\n(2)迎合，巴结～迎。～君之恶。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逢"},{"id":"glyph-kai-902e","script":"kai","character":"逮","reading":"dǎi；dài","description":"dài：(1)到，及力有未～。\n(2)捉拿～捕。～系。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逮"},{"id":"glyph-kai-9038","script":"kai","character":"逸","reading":"yì","description":"yì：(1)跑，逃跑，逃～。奔～。\n(2)散失～散。～史。～事。～闻。\n(3)安闲，安乐安～。～乐（安乐）。以～待劳。闲情～致。\n(4)超过一般超～。～兴（xìng）（超逸豪放的兴致）。～趣。～致。～品（超脱绝俗的艺术品）。～珠（特异的珍珠，喻人的品德）。\n(5)隐遁～士（隐居之士）。～民（ａ．旧时称遁世隐居不做官的人；ｂ．亡国后不在新朝代做官的人，亦作佚民”）。\n(6)放任，不受拘束～荡。飘～。骄奢淫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逸"},{"id":"glyph-kai-903b","script":"kai","character":"逻","reading":"luó","description":"遮拦\n用同捋”\n逻卒;巡行兵\n⒈巡察巡～。\n①思维的规律讲得有理，符合～辑。\n②研究思维的形式和规律的科学，叫逻辑学，也叫\"伦理学\"。\n③有时义同\"规律\"这是什么～辑？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逻"},{"id":"glyph-kai-903c","script":"kai","character":"逼","reading":"bī","description":"bī：(1)强迫，威胁～迫。～促。～命。～使。～问。～租。～债。\n(2)切近～近。～真。～视。～肖（xiào）（很相似）。\n(3)狭窄～仄。～侧。～狭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逼"},{"id":"glyph-kai-903e","script":"kai","character":"逾","reading":"yú","description":"yú：(1)越过，超过～期。～常（超过寻常）。～分（fèn）（过分）。～越。～恒（超过寻常）。\n(2)更加～甚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-逾"},{"id":"glyph-kai-9042","script":"kai","character":"遂","reading":"suí；suì","description":"suì：(1)顺，如意～心。～愿。\n(2)成功，实现未～。功成名～。\n(3)于是，就服药后头痛～止。\n(4)通达何往而不～”。\n(5)进，荐不能退，不能～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遂"},{"id":"glyph-kai-9047","script":"kai","character":"遇","reading":"yù","description":"yù：(1)相逢，会面，碰到～到。～见。～事。奇～。遭～。境～。\n(2)机会机～。际～。知～。\n(3)对待，款待待～。冷～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遇"},{"id":"glyph-kai-904d","script":"kai","character":"遍","reading":"biàn","description":"biàn：(1)全面，到处～历（周游）。～布。～及。～野。普～。\n(2)量词，次，回看了三～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遍"},{"id":"glyph-kai-904f","script":"kai","character":"遏","reading":"è","description":"è：(1)阻止～止。～制。～抑。怒不可～。\n(2)古同害”无～尔躬”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遏"},{"id":"glyph-kai-9053","script":"kai","character":"道","reading":"dào","description":"dào：(1)路，方向，途径～路。铁～。志同～合。\n(2)指法则、规律～理。～德。～义。得～多助，失～寡助。\n(3)学术或宗教的思想体系～学。传～。修～。\n(4)方法，办法，技术门～。医～。\n(5)指道家”（中国春秋战国时期的一个学派，主要代表人物是老聃和庄周）\n(6)指道教”（中国主要宗教之一，创立于东汉）～观（guàn）。～士。～姑。～行（háng）（僧道修行的功夫，喻技能和本领）。\n(7)指某些反动迷信组织会～门。一贯～。\n(8)说，讲～白。常言～。能说会～。\n(9)用语言表示情意～喜。～歉。～谢。\n(10)线条铅笔～儿。\n(11)中国历史上行政区域的名称。唐代相当于现在的省，清代和民国初年在省以下设道”。\n(12)某些国家行政区域的名称。\n(13)量词一～大河。两～门。上三～漆。\n(14)计量单位，忽米”的通称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-道"},{"id":"glyph-kai-9057","script":"kai","character":"遗","reading":"yí；wei","description":"给予;馈赠\n送交;交付\n以书遗操。\n⒈给予，赠送施～●～。\n⒈丢失～失。\n⒉漏掉，忽略～漏。～忘。\n⒊丢失的东西道不拾～。\n⒋漏掉的部分补～。纤悉无～。\n⒌抛弃～弃。\n⒍余，留，剩下～风。～留。不～余力。\n⒎特指死者留下的～嘱。～物。\n⒐不自觉地排泄大小便或精液～尿。～精。\n遗suí 1.谦虚，顺从。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遗"},{"id":"glyph-kai-9063","script":"kai","character":"遣","reading":"qiǎn","description":"qiǎn：(1)派，送，打发派～。～送。差（chāi）～。调（diào）～。～返（遣送回到原来的地方）。～散（sàn）。～词（说话、写文章运用词语）。\n(2)排解，发泄～闷。消～。～兴（xìng）。～怀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遣"},{"id":"glyph-kai-9065","script":"kai","character":"遥","reading":"yáo","description":"yáo：远～远。～望。～想。～瞻。～指。～瞩。～相呼应。路～知马力。～测。～感。～控。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遥"},{"id":"glyph-kai-906d","script":"kai","character":"遭","reading":"zāo","description":"zāo：(1)遇见，碰到（多指不幸或不利的事）。～遇。～难（nàn）。～受。～殃。～灾。～扰（婉辞，指受招待）。\n(2)周，圈周～。转了一～。\n(3)次一～生，两～熟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遭"},{"id":"glyph-kai-906e","script":"kai","character":"遮","reading":"zhē","description":"zhē：(1)挡～蔽。～挡。～拦。～阳。～没（mò）。～阴。\n(2)掩盖，掩蔽～丑。～盖。～瞒。～掩。～人耳目。\n(3)古同庶”，众多。\n(4)古同者”，这。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遮"},{"id":"glyph-kai-9075","script":"kai","character":"遵","reading":"zūn","description":"zūn：沿着，依照，按照～守。～照。恪～。～循。～行。～养时晦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-遵"},{"id":"glyph-kai-907f","script":"kai","character":"避","reading":"bì","description":"bì：(1)躲，设法躲开～雨。～暑。～世。～讳。回～。～重就轻。～世绝俗。\n(2)防止～免。～孕。～嫌。～雷针。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-避"},{"id":"glyph-kai-9080","script":"kai","character":"邀","reading":"yāo","description":"yāo：(1)约请～请。～集。应～。\n(2)取得，希求～赏。～准。～宠。～功请赏。\n(3)阻留～击（拦击）。～截。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邀"},{"id":"glyph-kai-9091","script":"kai","character":"邑","reading":"yì","description":"yì：(1)城市，都城城～。都～。\n(2)旧指县～人（同乡的人）。～庠（明清时称县学）。～宰。\n(3)古代诸侯分给大夫的封地采～。\n(4)古同悒”，愁闷不安。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邑"},{"id":"glyph-kai-9093","script":"kai","character":"邓","reading":"dèng","description":"古国名\n在今河南省邓县。公元前678年为楚所灭\n古地名\n春秋蔡地,后属楚。在今河南省郾城县东南\n战国楚地,秦置邓县,是故邓侯国。在今湖北省襄樊市北\n战国魏邑,在今河南省孟县西南\n邓 dèng姓。\n勇抗敌，最后弹尽舰伤，遂驾舰撞击敌舰，不幸中敌鱼雷，与全舰官兵一起壮烈牺牲。\n迎。'文革'中被迫害致死。\n月29日在南京被蒋介石秘密杀害。\n海，后因舟中火起，为倭军所乘，遂战死。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邓"},{"id":"glyph-kai-90a3","script":"kai","character":"那","reading":"nà；nǎ；nèi；nā","description":"nà：指较远的时间、地方或事物，与这”相对～里。～个。～样。～些。～时。～么。\n这；\nnǎ：同哪”（一）（中国大陆地区已不用）。\n这；\nnèi：义同（一），那”和一”连读的合音，但指数量时不限于一～个。～五年。\n这；\nnā：姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-那"},{"id":"glyph-kai-90a6","script":"kai","character":"邦","reading":"bāng","description":"bāng：国友～。邻～。～交（国和国之间的正式外交关系）。～国（国家）。～人（本国的人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邦"},{"id":"glyph-kai-90aa","script":"kai","character":"邪","reading":"xié；yá；yé；yú；xú","description":"xié：(1)不正当，不正派～恶（è）。～念。～说。\n(2)中医指引起疾病的环境因素寒～。风～。\n(3)迷信的人指鬼神给予的灾祸中（zhòng）～。\n(4)妖异怪诞～魔。～术。\n(5)古同斜”。\n正；\nyá：古同玡”，琅玡山。\n正；\nyé：古同耶”，疑问词。\n正；\nyú：古同餹”。\n正；\nxú：古同徐”，缓慢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邪"},{"id":"glyph-kai-90ae","script":"kai","character":"邮","reading":"yóu","description":"传递文书的驿站\n指传送文书的人\n古代井田间\n⒈寄递信件、金钱、物品等的专设机构、人员～局。～递员。\n⒉有关邮务的买～票。收～费。～寄。～购。\n⒊〈古〉通\"尤\"。过错，罪过不知其～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邮"},{"id":"glyph-kai-90bb","script":"kai","character":"邻","reading":"lín","description":"周朝地方基层组织的户口单位\n相连接的家户。邻居;邻国\n⒈接近的，住处靠近的人家～近。～国。～居。四～。比～。\n⒉〈古〉一种居民组织。五家为～，五～为里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-邻"},{"id":"glyph-kai-90c1","script":"kai","character":"郁","reading":"yù","description":"郁夷\n古地名『置县。在今陕西省陇县西\n物实无中核者谓之郁\n郁 〈形〉\n文采美盛\n丰盛\n⒈茂盛，树木丛生葱～。\n⒉忧愁，愁闷忧～。抑～。\n⒊草木腐臭～气。\n⒋形容香气馥～。\n⒌〈古〉通\"燠\"。\n①有文采文采～ ～。\n②忧愁，愁闷～ ～不乐。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郁"},{"id":"glyph-kai-90ca","script":"kai","character":"郊","reading":"jiāo","description":"jiāo：城外～区。～外。～游。～野。荒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郊"},{"id":"glyph-kai-90ce","script":"kai","character":"郎","reading":"láng；làng","description":"láng：(1)对年轻男子的称呼大～。～才女貌。\n(2)对某种人的称呼货～。女～。\n(3)旧时妻称夫或情人～君。\n(4)封建时代的官名～中（ａ．古官名；ｂ．中医医生）。侍～。员外～。\n(5)姓。\nlàng：〔屎壳～〕蜣螂”的俗称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郎"},{"id":"glyph-kai-90d1","script":"kai","character":"郑","reading":"zhèng","description":"⒈周代诸侯国名。在今河南省新郑一带。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郑"},{"id":"glyph-kai-90e8","script":"kai","character":"部","reading":"bù","description":"bù：(1)全体中的一份～分（分”读轻声）。外～。腹～。局～。全～。～件。～位（位置）。\n(2)机关企业按业务范围分设的单位外交～。编辑～。～队（军队）。\n(3)具有统属关系所～五十人。～下。～将。～属。～首。～落（luò）。\n(4)安置安排～署。\n(5)量词一～小说。三～汽车。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-部"},{"id":"glyph-kai-90ed","script":"kai","character":"郭","reading":"guō","description":"guō：(1)城外围着城的墙城～。爷娘闻女来，出～相扶将”。\n(2)物体的外框或外壳。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-郭"},{"id":"glyph-kai-90fd","script":"kai","character":"都","reading":"dōu；dū","description":"dū：(1)大都市～市。～会。通～大邑。\n(2)一国的最高行政机关所在的地方，京城首～。国～。京～。建～。\n(3)美好雍容闲雅，甚～”。～丽。～雅。\n(4)总～为一集。\n(5)居～卿相之位”。\n(6)古代称头目、首领。\n(7)姓。\n皆；全；\ndōu：(1)全，完全～要。功课学得～不错。\n(2)表示语气的加重一动～不动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-都"},{"id":"glyph-kai-9102","script":"kai","character":"鄂","reading":"è","description":"è：(1)中国湖北省的别称。\n(2)古同谔”，正直的话。\n(3)古同愕”，惊讶。\n(4)古同萼”，花托。\n(5)边界纷被丽而亡～”。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄂"},{"id":"glyph-kai-9119","script":"kai","character":"鄙","reading":"bǐ","description":"bǐ：(1)中国周代地方组织单位之一，五百家为一鄙～师（古官名，周制每县五鄙，鄙师”掌其鄙之政令祭祀）。\n(2)郊野之处，边远的地方边～。\n(3)粗俗～陋。～俗。～夫。～近（庸俗浅近）。\n(4)轻蔑，看不起～视。～夷。～弃。～薄。\n(5)品质低劣卑～。\n(6)谦辞，用于自称～人。～老。～见。\n(7)吝啬～吝。～诈（贪吝诈伪）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鄙"},{"id":"glyph-kai-9149","script":"kai","character":"酉","reading":"yǒu","description":"yǒu：(1)地支的第十位，属鸡。\n(2)用于计时～时（下午五点至七点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酉"},{"id":"glyph-kai-914c","script":"kai","character":"酌","reading":"zhuó","description":"zhuó：(1)斟酒对～。\n(2)饮酒宴会便～。清～。\n(3)考虑，度量～办。～定。～情。斟～。～加修改。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酌"},{"id":"glyph-kai-914d","script":"kai","character":"配","reading":"pèi","description":"pèi：(1)两性结合～偶。～种（zhǒng）。\n(2)相互分工合作～合。～器。\n(3)用适当的标准加以调和～料。～制。～伍。～药。～色。～餐。\n(4)有计划地分派、安排～备。～置。～给（jǐ）。分～。搭～。\n(5)把缺少的补足～套。～乐（yuè）。装～。\n(6)衬托，陪衬～搭。～角儿（juér）。～殿§花～绿叶。\n(7)够得上～得上。\n(8)古代把罪人遣放到边远地区充军～军。发～。刺～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-配"},{"id":"glyph-kai-9152","script":"kai","character":"酒","reading":"jiǔ","description":"jiǔ：用高粱、米、麦或葡萄等发酵制成的含乙醇的饮料白～。啤～。料～。鸡尾～。茅台～。～浆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酒"},{"id":"glyph-kai-9157","script":"kai","character":"酗","reading":"xù","description":"xù：沉迷于酒，撒酒疯～酒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酗"},{"id":"glyph-kai-915d","script":"kai","character":"酝","reading":"yùn","description":"逐渐造成\n⒈酿酒春～夏成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酝"},{"id":"glyph-kai-9163","script":"kai","character":"酣","reading":"hān","description":"hān：(1)酒喝得很畅快～饮。半～。～醉。酒～耳热。\n(2)尽量，痛快～畅。～赏（恣意游赏）。～眠。～然。\n(3)浓，盛～春（春色正浓）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酣"},{"id":"glyph-kai-9165","script":"kai","character":"酥","reading":"sū","description":"sū：(1)酪，用牛羊奶制成的食物～酪。～油。\n(2)松脆，多指食物～脆。～糖。桃～。\n(3)柔腻松软～胸。～松。\n(4)身体酸软无力～软。～麻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酥"},{"id":"glyph-kai-916a","script":"kai","character":"酪","reading":"lào","description":"lào：(1)用动物的乳汁做成的半凝固食品奶～。干～。～蛋白（一种含磷的复合蛋白。乳中蛋白质的主要成分。营养价值较高。可制成干酪）。\n(2)用果实做的糊状食品果～。杏仁～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酪"},{"id":"glyph-kai-916c","script":"kai","character":"酬","reading":"chóu","description":"chóu：(1)劝酒～酢。\n(2)用财物报答～劳。～谢。～金。报～。\n(3)交际往来应（yìng）～。～对。～和（hè）（用诗词应答）。～唱（用诗词互相赠答）。\n(4)实现愿望壮志未～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酬"},{"id":"glyph-kai-9171","script":"kai","character":"酱","reading":"jiàng","description":"用麦、面、豆等发酵制成的调味品\n将鱼、肉、蔬、果捣烂制成的糊状食品\n用酱或酱油腌制\n⒈豆、麦等经过发酵制成的调味品甜～。辣椒～。豆瓣～。\n⒉用酱腌制或加有酱的食品～肉。～黄瓜。杂～面。\n⒊像酱样子的糊状食品肉～。虾～。蕃茄～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酱"},{"id":"glyph-kai-9175","script":"kai","character":"酵","reading":"jiào","description":"jiào：有机物由于某些菌或酶而分解称发酵”。能使有机物发酵的真菌称酵母菌”。亦称酵母”、酿母”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酵"},{"id":"glyph-kai-9177","script":"kai","character":"酷","reading":"kù","description":"kù：(1)残忍、暴虐到极点～刑。～吏。残～。严～。冷～。～滥。～虐。\n(2)极，甚，程度深～暑。～热。～寒。～爱。～似。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酷"},{"id":"glyph-kai-9178","script":"kai","character":"酸","reading":"suān","description":"suān：(1)像醋的气味或味道～菜。～溜溜。～梅。～甜。～奶。～枣。\n(2)化学上称能在水溶液中产生氢离子的化合物，分无机酸”、有机酸”两大类盐～。碳～。硝～。硫～。～碱度。\n(3)讥讽人的迂腐穷～‘～。\n(4)悲痛，伤心～楚。辛～（亦作酸辛”）。～苦。～怆。～怀。\n(5)因疲劳或疾病引起的微痛而无力的感觉～痛。腰～腿疼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酸"},{"id":"glyph-kai-917f","script":"kai","character":"酿","reading":"niàng","description":"酝酿,逐渐形成\n⒈利用发酵作用制造，一般指造酒～造。～酒。\n⒉酒佳～。\n⒊逐渐形成～成。\n⒋蜜蜂制蜜～蜜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酿"},{"id":"glyph-kai-9187","script":"kai","character":"醇","reading":"chún","description":"chún：(1)酒味厚～酒。～醪。\n(2)纯粹～和（性质或味道纯正平和）。～厚（气味、滋味纯正浓厚）。～美。～化。\n(3)同淳”。\n(4)有机化合物的一类乙～。胆固～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醇"},{"id":"glyph-kai-9189","script":"kai","character":"醉","reading":"zuì","description":"zuì：(1)饮酒过量，神志不清～汉。～鬼。～意。～拳（一种拳术，步法上突出东倒西歪的醉态）。～生梦死。～翁之意不在酒。\n(2)沉迷，过分爱好～心。沉～。陶～（很满意地沉浸在某种境界或思想活动中）。\n(3)用酒泡制的～枣。～虾。～蟹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醉"},{"id":"glyph-kai-918b","script":"kai","character":"醋","reading":"cù","description":"cù：一种调味用的液体，味酸米～。熏～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醋"},{"id":"glyph-kai-9192","script":"kai","character":"醒","reading":"xǐng","description":"xǐng：(1)睡眠状态结束或尚未入睡如梦方～。\n(2)酒醉、麻醉或昏迷后神志恢复正常状态～酒。\n(3)泛指头脑由迷糊而清楚～悟。觉（jué）～。清～。提～。猛～。\n(4)明显、清楚～目。～眼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醒"},{"id":"glyph-kai-91c7","script":"kai","character":"采","reading":"cǎi；cài","description":"cǎi：(1)摘取～撷。～花。～摘。～制。\n(2)选取，搜集，开发，利用～访（搜集寻访）。～纳（接受意见）。～集。～伐。～购。～掘。～写。\n(3)神色，精神神～。精～。\n(4)同彩”。\n(5)古代指官。\n〔～～〕盛多的样子。\ncài：〔～地〕古代卿大夫的封地。亦称采邑”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-采"},{"id":"glyph-kai-91ca","script":"kai","character":"释","reading":"shì","description":"解释\n⒈放，放下，放弃～放。开～。如～重负。手不～卷。\n⒉排解，消除，消溶～难。～疑。冰～。\n⒊说明，解说～义。解～。注～。\n释yì 1.喜悦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-释"},{"id":"glyph-kai-91cc","script":"kai","character":"里","reading":"lǐ","description":"内,中。与外相反\n⒈长度单位1公～为1000米，合二市～，即三百丈。\n⒉〈古〉一种居民组织。五家为邻，五邻为～。今指街坊～弄。邻～。\n⒋衣服里层绿衣黄～。〈引〉里面，内部城市～。手掌～。柜子～。\n⒌物体内层，跟\"表\"、\"面\"相对～层。～面。袜～儿。被盖～子。表～如一。\n⒍一定范围以内山～。那～。哪～？黑夜～。\n①靠左边，靠里的那边。\n②〈方〉内行知识～手。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-里"},{"id":"glyph-kai-91cd","script":"kai","character":"重","reading":"zhòng；chóng","description":"zhòng：分量大；程度深；重要，重视。chóng：重复，重叠，再一次。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-91ce","script":"kai","character":"野","reading":"yě","description":"yě：(1)郊外，村外～外。～景。～游。～趣。～餐。～战。四～。郊～。\n(2)界限，范围分～。视～。\n(3)指不当政的地位，与朝（cháo）”相对朝～。下～。在～。～史。\n(4)不讲情理，没有礼貌～蛮。粗～。\n(5)巨大而非分的欲望～心。\n(6)不受约束心玩儿～了。\n(7)不是人工驯养或栽培的（动物或植物）～生。～兽。～味。～花。～菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-野"},{"id":"glyph-kai-91cf","script":"kai","character":"量","reading":"liàng；liáng","description":"liáng：(1)确定、计测东西的多少、长短、高低、深浅、远近等的器具～具。～杯。～筒。～角器。\n(2)用计测器具或其他作为标准的东西确定、计测计～。测～。～度。～体温。\n(3)估计，揣测估～。思～。打～。\n质；\nliàng：(1)古代指斗、升一类测定物体体积的器具度～衡。\n(2)能容纳、禁受的限度酒～。气～。胆～。度～。\n(3)数的多少数～。质～。降雨～。限～供应。\n(4)审度～刑。～才录用。～体裁衣（喻从实际情况出发办事）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-量"},{"id":"glyph-kai-91d1","script":"kai","character":"金","reading":"jīn","description":"jīn：(1)一种化学元素，符号Ａｕ，原子序数79，黄赤色，质软黄～。～子。～笔。\n(2)金一类的，具有光泽、延展性，容易传热和导电的固体的通称（汞除外）。～属。五～（旧指金银铜铁锡）∠～（两种或多种金属混合而成的金属）。～文（铸或刻在商周青铜器上的铭文，旧称钟鼎文”）。\n(3)钱现～。基～。挥～如土。\n(4)指兵器或金属制的乐器～革（兵器甲铠的总称，引申指战争）。～声（ａ．钲声；ｂ．钟声）。～鼓（锣鼓）。\n(5)中国古代乐器八音之一。\n(6)喻尊贵、贵重、难得、持久、坚固、有光泽等～兰（友情深）。～刚（梵语意译，喻牢固、锐利、能摧毁一切）。～瓯（ａ．盛酒器；ｂ．喻疆土完整）。～城汤池。\n(7)一些动、植物因颜色似金而得名～鱼。～乌（太阳）。～龟。～丝猴。\n(8)中国朝代名～代。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-金"},{"id":"glyph-kai-9274","script":"kai","character":"鉴","reading":"jiàn","description":"中国古代用青铜制成的镜子\n⒈〈古〉用来盛水或冰的大盆。\n⒉照影水清可～。\n⒊镜子以铜为～，可以正衣冠。〈引〉可以引为儆戒或教训的事引为～戒。殷～不远。\n⒋观察，审察，区别～赏。～定优劣。～别真假。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鉴"},{"id":"glyph-kai-9488","script":"kai","character":"针","reading":"zhēn","description":"缝缀衣物的用具。也叫引线”\n⒈缝、补衣物时引线用的一种细长的工具缝～。穿～引线。\n⒉形状像针的东西松～。大头～。金～菜。钟表上的时～、分～、秒～。\n⒊用于医疗的有关针的器具、药品等～头。银～。扎～。打～。防疫～。～剂。～灸疗法。～刺麻醉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-针"},{"id":"glyph-kai-9489","script":"kai","character":"钉","reading":"dìng","description":"钉子\n通常是圆锥形,有尖头或尖顶的木料、金属或其他材料做的钉状物\n紧跟不放,监视\n催促;监督;紧迫\n用钉\n①竹、木、金属等制成的细棍形物件。一端有扁平的头，另一端尖锐，主要起固定或连接作用，也可以用来悬挂物品。\n②紧跟着不放松～住对方。\n③督促；催问经常～着点。\n④同'盯'。又见dìng。\n【钉螺】软体动物。螺壳厚，高10毫米左右，螺层7个左右，雌雄异体。生活在杂草丛生的河湖、沟渠、池塘。水陆两栖。是日本血吸虫的中间宿主。\n【钉梢】暗中紧跟在别人身后以监视别人的行动。又作盯梢。\n【钉是钉， 铆是铆】见【丁是丁，卯是卯】。\n①把钉子捶入～皮鞋。\n②用针线缝住～衣扣。又见dīng。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钉"},{"id":"glyph-kai-9493","script":"kai","character":"钓","reading":"diào","description":"引申为诱取\n①将饵挂在钓钩上放入水中诱捕鱼虾等～鱼。\n③钓鱼钩垂～。\n【钓鱼岛】中国台湾省的附属岛屿。在台湾岛东北约180公里处，面积约5平方公里。自古以来是中国的领土。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钓"},{"id":"glyph-kai-9499","script":"kai","character":"钙","reading":"gài","description":"一种银白色的相当柔软的碱土族二价金属元素,在空气中很快失去光泽,受热时以明亮的火焰燃烧,主要用于合金和各种冶金过程中,常用作清除剂;自然界中不单独存在,常以化合\n缺钙;钙化\n钙gài金属元素。符号ca。白色，化学性质活泼。钙的化合物在建筑工程上和医药上用途很广。人的血液和骨骼中都含有钙，缺钙会引起佝偻病﹑手足抽搦等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钙"},{"id":"glyph-kai-949d","script":"kai","character":"钝","reading":"dùn","description":"呆;笨拙\n①不锋利；不锐利刀～了。\n②笨拙；不灵活迟～。\n【钝角】大于直角小于平角的角。若a为钝角，则90°","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钝"},{"id":"glyph-kai-949e","script":"kai","character":"钞","reading":"chāo","description":"掠取;抢掠◇作抄”\n誊写。也作抄”\n纸币名。现在称纸币为钞票,简称钞\n泛指钱\n⒈纸币～票。现～。\n⒉通\"抄\"。誊写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钞"},{"id":"glyph-kai-949f","script":"kai","character":"钟","reading":"zhōng","description":"钟磬置水中。\n独以此钟名。\n如钟鼓不绝。\n⒈一种金属制的响器，中空，悬挂在架上，用槌敲击发声撞～。打～。警～。\n⒉计时器闹～。电～。石英～。\n⒊时间，小时五分～。八点～。\n⒋杯子，〈古〉一种盛酒器聚酒千～。\n⒌专注，特别～情。～爱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钟"},{"id":"glyph-kai-94a0","script":"kai","character":"钠","reading":"nà","description":"一种银白色的软的、蜡状而有延展性的金属元素,原子序数11,其化学性质很活泼,用在钠蒸气灯中,尤其在内燃机用的致冷阀中作为一种传热剂","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钠"},{"id":"glyph-kai-94a2","script":"kai","character":"钢","reading":"gāng","description":"⒈经过精炼的铁，含碳百分之0.15至百分之1.7,不含磷、硫等杂质。它是工业上极重要的基本原料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钢"},{"id":"glyph-kai-94a5","script":"kai","character":"钥","reading":"yào","description":"门直闩。上穿横闩下插地上的直木\n枢要,重要之处\n钥匙\n指锁\n每夜必手自关门下钥,其钥为外洋上等货,且钥匙仅有一枚,甲自佩之。至明晨,始手\n⒈锁。\n⒈锁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钥"},{"id":"glyph-kai-94a6","script":"kai","character":"钦","reading":"qīn","description":"旧时对帝王的决定、命令或其所做的事冠以钦”字,以示崇高与尊敬\n敬佩\n⒈恭敬，敬重～爱。～佩。\n⒉〈古〉有关皇帝的～赐。～命。～差大臣。\n钦qìn 1.用手按。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钦"},{"id":"glyph-kai-94a7","script":"kai","character":"钧","reading":"jūn","description":"制陶器所用的转轮\n⒊敬词。对尊长或上级的敬称～座。～鉴。～谕。\n⒋〈古〉通\"均\"。平均。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钧"},{"id":"glyph-kai-94a9","script":"kai","character":"钩","reading":"gōu","description":"形状弯曲,用于探取、悬挂器物的用品。可分为钓钩、挂钩、带钩等\n⒈弯曲的器具，用于悬挂或探取东西等火～儿。钓鱼～。挂衣～子。\n⒉形状像钩的东西～鼻子。蝎子的～儿。\n⒌缝纫编结法之一～边。～花。\n⒍同\"gōu㈠勾\n⒉\"，描绘～图样。\n钩qú 1.见\"钩町\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钩"},{"id":"glyph-kai-94ae","script":"kai","character":"钮","reading":"niǔ","description":"器物上面可以提携或系绳带的部分\n交互而成的扣结\n器物上用手操作、转动的部分\n钮niǔ扣合衣物的东西～扣子。塑料～扣。\n钮chǒu 1.刑具。枷锁镣铐之类。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钮"},{"id":"glyph-kai-94b1","script":"kai","character":"钱","reading":"qián","description":"金属货币。特指铜钱\n⒈货币～币。铜～。金～。三块～。\n⒉费用，款项米～。菜～。一笔～。\n⒊财物无～难办。有～有势。\n⒋重量单位十分为一～。十～为一两。\n钱jiǎn 1.古农具名。臿属，似今之铁铲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钱"},{"id":"glyph-kai-94b3","script":"kai","character":"钳","reading":"qián","description":"古刑具。束颈的铁圈\n夹持东西的用具\n古代刑罚。用铁圈束颈、手、足\n⒈夹东西的工具止血～。老虎～子。\n⒉用工具夹住。〈引〉用强力限制，约束～制。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钳"},{"id":"glyph-kai-94bb","script":"kai","character":"钻","reading":"zuàn","description":"钻研,集中精力学习,推究事理\n⒉细致深入地研究～研。她很有～劲。\n⒊想方设法巴结有权势的人，以谋取私利～营。\n⒈钻子，穿孔打眼的用具电～。手摇～子。\n⒉穿孔，打眼。\n钻qián 1.铁钳之类的刑具。参见\"钻钻\"。 2.同\"钳\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钻"},{"id":"glyph-kai-94be","script":"kai","character":"钾","reading":"jiǎ","description":"碱金属族的一价金属元素,呈银白色,质软,有光泽,熔点低,比钠更活泼,在空气中很快氧化,与水激烈反应,放出氢气而自行着火,主要用作还原剂及用于合成中\n╠元素符号k\n钾jiǎ化学元素。符号k。银白色软金属，化学性质活泼，容易氧化，宜保存在煤油中。钾的化合物用途广泛，也是极重要的肥料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钾"},{"id":"glyph-kai-94c1","script":"kai","character":"铁","reading":"tiě","description":"铁制的器物\n⒈金属元素。符号fe。灰白色，质坚硬，有光泽，富于延伸性，在潮湿空气中易氧化生绣。在工业上用途很大，可以炼钢，制造各种机械、器具等。\n⒉〈喻〉坚固，坚硬、坚强，坚定铜墙～壁。～拳，～人。～姑娘队。\n⒊〈喻〉确定不移～证。～的纪律。\n⒋〈喻〉残暴或精锐～蹄。～骑。\n⒌兵器的代称手无寸～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铁"},{"id":"glyph-kai-94c3","script":"kai","character":"铃","reading":"líng","description":"铃的鸣响或声音,可作为信号\n铃状物\n⒈金属制成的响器，中有小锤，振动发音车～。电～。打～。\n⒉像铃状的东西哑～。棉～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铃"},{"id":"glyph-kai-94c5","script":"kai","character":"铅","reading":"qiān","description":"青金\n古时也指锡类\n一种重而柔软、有延展性、可塑性而没有弹性的二价或四价的金属元素,元素符号pb。原子序数82,刚切割时呈蓝白色,但在潮湿空气中很快失去光泽而变暗灰色,它大多以化合\n状态存在\n⒈金属化学元素。符号pb。银灰色，质软，熔点低。用作制电缆、煤气管、蓄电池等∠金用做铅字、轴承、电线包皮等。\n⒉石墨～笔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铅"},{"id":"glyph-kai-94d0","script":"kai","character":"铐","reading":"kào","description":"戴上手铐\n⒈束缚手的刑具手～子。\n⒉戴手铐将罪犯～起来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铐"},{"id":"glyph-kai-94db","script":"kai","character":"铛","reading":"chēng","description":"锒铛。锁系囚人的铁索\n女子的耳饰\n钟鼓的声音\n温器,似锅,三足\n烙饼或做菜用的平底浅锅\n⒈一种平底浅锅。\n铛dāng 1.见\"锒铛\"。 2.女子的耳饰。 3.象声词。形容撞击金属的声音。\n铛tāng 1.见\"铛?\"。 2.一种小铜鼓。 3.古兵器名。形如半月，有柄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铛"},{"id":"glyph-kai-94dc","script":"kai","character":"铜","reading":"tóng","description":"首衔同凡。\n①金属元素。符号cu。淡紫红色，延展性﹑导电性和导热性都很好。古谓之赤金。铜的合金是电气工业﹑机械工业﹑国防工业等的重要原料。\n③比喻坚强﹑牢固。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铜"},{"id":"glyph-kai-94dd","script":"kai","character":"铝","reading":"lǚ","description":"金属元素，符号 Al，质轻，具有良好的延展性、导电性和耐蚀性。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-94ed","script":"kai","character":"铭","reading":"míng","description":"牢记不忘\n铭心立报,永矣无贰。\n⒈刻写在器物上记述生平、事业或警语等的文字鼎～。墓志～。座右～。\n⒉在器物上刻字～刻。也〈喻〉深刻记住～记在心。\n⒊文体的一种陋室～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铭"},{"id":"glyph-kai-94f2","script":"kai","character":"铲","reading":"chǎn","description":"铲子\n古兵器。形似铲\n削平;铲除\n②用锹或铲摄取或清除～垃圾。\n【铲球】足球运动中倒地抢截球的技术。一般用在对手带球或接球越过自己，来不及用其他方法拦截的情况下。\n⒈削平或撮取东西的工具铁～子。锅～儿。\n⒉使用锹或铲～煤。将土～平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铲"},{"id":"glyph-kai-94f6","script":"kai","character":"银","reading":"yín","description":"银制的器物\n⒈ 化学元素，金属，白色有光泽。符号ag。质柔软，富延伸性，是导热、导电的良好导体。在空气中不易氧化。可制硬币、器具等。\n⒉［银子］旧时以银鋳成块状的一种货币。\n⒊［银行］办理储蓄、放款、汇兑等业务的机构。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-银"},{"id":"glyph-kai-94f8","script":"kai","character":"铸","reading":"zhù","description":"造就","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铸"},{"id":"glyph-kai-94fa","script":"kai","character":"铺","reading":"pù","description":"铜器名。豆属。其上为一平的直壁浅盘。铺与豆的区别在于它没有细长的把柄,在盘下连铸一较宽的高圈足\n把东西展开或摊平\n⒈商店店～。饭～子。杂货～儿。\n⒉床床～。搭个～。\n⒊旧时指驿站。现多用于地名十里～。\n⒈陈设，展开，摊平摆置～设。～开。～平。～纸。～轨。平～直叙。\n⒉门环的底座金～交映。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铺"},{"id":"glyph-kai-94fe","script":"kai","character":"链","reading":"liàn","description":"链条\n用索环栓住、捆绑或联接\n⒈用金属环连套构成的长条铁～子。表带～。\n⒉海洋上计算距离的一种单位，一～为十分之一海里，合185.2米。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-链"},{"id":"glyph-kai-9500","script":"kai","character":"销","reading":"xiāo","description":"溶化;消融\n通消”。清失;消除;\n⒈熔化金属，泛指熔化～金。～炼。\n⒉除去，解除～假。撤～。\n⒊售，出卖供～。推～。畅～。\n⒋消费开～。\n⒌通\"消\"。消失，消灭～声匿迹。\n⒎将销子推上把窗子～好。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-销"},{"id":"glyph-kai-9501","script":"kai","character":"锁","reading":"suǒ","description":"一种用铁环钩连而成的刑具\n链子\n⒈安在门、箱、柜等的开合处，使人不能随便打开的器具铁～。弹子～。\n⒉用锁锁住～门。～好箱子。\n⒊封闭封～。\n⒋链子～链。枷～。\n⒌紧皱眉头双眉深～。\n⒍一种缝纫法，针脚密，线斜交或钩连，多用于衣物边沿上～边。～扣眼。\n⒎像锁的东西石～。金～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锁"},{"id":"glyph-kai-9504","script":"kai","character":"锄","reading":"chú","description":"锄 〈动〉\n用锄头整理田地,除草\n根除,铲除\n①松土和除草用的农具～头。\n②用锄头松土除草。\n③铲除～奸铲霸。\n【锄奸】铲除通敌的奸细。\n⒈一种松土、除草等的工具。\n⒉使用锄～地。～草。\n⒊铲除～奸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锄"},{"id":"glyph-kai-9505","script":"kai","character":"锅","reading":"guō","description":"形状像锅的东西\n车鈍。即车轴外面的铁圈\n⒈煮炒食物等的器具炒菜～。电饭～。电煮～。\n⒉像锅的烟袋～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锅"},{"id":"glyph-kai-9508","script":"kai","character":"锈","reading":"xiù","description":"金属表面所生的氧化物\n锈病\n生锈\n⒈金属表面因受潮腐蚀而生成的氧化物铁～。铜～。\n⒉生锈刀～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锈"},{"id":"glyph-kai-950b","script":"kai","character":"锋","reading":"fēng","description":"借指刀、剑等有刃的兵器\n泛指器物尖锐犀利的部分\n①器物尖锐犀利的部分针～。笔～。\n②带头的，在前面的先～。前～。〈喻〉锐气，才干或言论的锐利～芒。谈～。词～。\n⒉锋利京师所制兵器，多不～利。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锋"},{"id":"glyph-kai-950c","script":"kai","character":"锌","reading":"xīn","description":"一种蓝白色的晶状的二价金属元素,有低至中等的硬度,纯时有延性,主要用作钢铁的保护性涂层\n锌白\n锌版","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锌"},{"id":"glyph-kai-9510","script":"kai","character":"锐","reading":"ruì","description":"精锐的军队或士卒\n锐气,勇往直前的气势\n力量,劲\n锐利的兵器\n锋利\n长其尾\n⒉感觉灵敏敏～。目光～利。\n⒊勇往直前的气势～气。～不可当。\n⒋急剧，骤然～增。～变。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锐"},{"id":"glyph-kai-9519","script":"kai","character":"错","reading":"cuò","description":"互相磨擦\n①参差；错杂犬牙交～。\n②物体相对摩擦～牙。\n③相对行动时避开而不碰上～车。\n④使办事的时间不冲突～开上下班时间。\n⑤不正确的～话、～字。\n⑥过错；错处我说的设～。\n⑧在凹纹中镶上或涂上金、银等～金。\n⑨打磨玉石的石头。\n⑩打磨玉石攻～。\n【错爱】谦辞。表示感谢对方爱护。\n【错别字】错字和别字的总称。\n【错愕】仓促惊讶；惊愕。\n【错金银】器物上的金银纹饰。镶金丝或金片的称错金，镶银片或银丝的称错银。在春秋时期已用于青铜器。\n【错落】交错纷杂～有致。\n【错综复杂】形容形势或情况纵横交叉，非常复杂。\n膳毋悖。\"郭沫若等集校﹕\"古本'错'作'醋'，刘本﹑朱东光本同。\"一说设置，安置。集校又引张文虎曰﹕\"'错'犹置也，下文云'凡置彼食'是也。朱本讹为'醋'。\" 7.通\"促\n\"。仓促，急迫。参见\"错愕\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-错"},{"id":"glyph-kai-951a","script":"kai","character":"锚","reading":"máo","description":"船舶停泊时沉入水底、用以固定船位的器具。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-9521","script":"kai","character":"锡","reading":"xī","description":"素符号sn\n通緆”。细麻布\n和尚所用锡杖的简称\n通赐”。给予;赐给\n申锡无疆,\n⒈金属化学元素之一。符号sn。银白色，有光泽，质软，富于延伸性，在空气中不易起变化。用于制马口铁、青铜焊料、软管等。\n⒉通\"赐\"。赏赐，赐给。\n锡tì 1.假发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锡"},{"id":"glyph-kai-9523","script":"kai","character":"锣","reading":"luó","description":"带卷边的青铜圆盘\n鸣锣会集。\n鸣锣传递。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锣"},{"id":"glyph-kai-9524","script":"kai","character":"锤","reading":"chuí","description":"八铢\n十二两\n六铢\n槌子,俗称榔头\n古兵器名。柄的上头有一个金属圆球\n秤砣\n锤形物\n①古代兵器。柄上有一个金属圆球。\n②像锤的东西秤～。\n③敲打东西的用具铁～、钉～。\n④用锤子敲打千～百炼。\n【锤炼】\n①磨练。\n②努力钻研，反复加工精心～。\n⒈秤上平衡重量的金属块秤～。\n⒉敲击东西的工具木～子。铁～儿。\n⒊用锤敲击～打。千～百炼。\n⒋像锤的东西纺～。钟～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锤"},{"id":"glyph-kai-9525","script":"kai","character":"锥","reading":"zhuī","description":"形如尖锥的东西\n⒈一端尖锐可钻孔的工具圆～子。\n⒊用锥形的东西钻在这儿～个孔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锥"},{"id":"glyph-kai-9526","script":"kai","character":"锦","reading":"jǐn","description":"古指锦袍\n旧时书信中的敬词\n⒈带有彩色花纹的丝织品蜀～。～旗。～标。～绣。～缎。\n⒉色彩鲜艳华丽～霞。～羽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锦"},{"id":"glyph-kai-952e","script":"kai","character":"键","reading":"jiàn","description":"车辖。安在车轴两端,管住车轮不脱离轴的铁棍\n钥匙\n竖着插的门闩\n⒈车轴上的铁条，用以管住车轮。又叫\"辖\"。\n⒉插在门上，用以关锁门户的金属棍子。\n⒊琴、电脑、发报机等物上可以按动的部分～盘。\n⒋〈古〉称钥匙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-键"},{"id":"glyph-kai-952f","script":"kai","character":"锯","reading":"jù；jv","description":"锯形物\n古刑具\n用锯子切割\n⒈能断木、石、金属等的一种工具。用钢片或钢条制成木～。电～。\n⒉用锯断物～树枝。～钢管。\n锯jū 1.用锔子补接器物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锯"},{"id":"glyph-kai-9530","script":"kai","character":"锰","reading":"měng","description":"一种灰白色多价金属元素,通常硬而脆,类似铁但无磁性\n锰钢\n锰měng金属化学元素。符号mn。赤灰色，质坚而脆。锰与铁的合金叫\"锰钢\"，它是特殊钢，供做火车的车轮等。二氧化～是制干电池的原料，也供瓷器、玻璃着色等用。高～\n酸钾供药用，可作消毒灭菌剂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锰"},{"id":"glyph-kai-9539","script":"kai","character":"锹","reading":"qiāo","description":"掘土器,用于开沟掘土、铲取什物,\n用锹挖掘\n⒈挖土或铲取东西的工具铁～。\n⒉用锹铲～土。～煤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锹"},{"id":"glyph-kai-953b","script":"kai","character":"锻","reading":"duàn","description":"锤击\n罗织罪状,陷人于罪\n锻铁用的砧石\n锻 duàn把金属加热后锤打加工。\n【锻锤】金属压力加工用的机器，由动力带动锤头上下移动而产生压力。\n【锻铁】用生铁精炼而成，含碳量在0.15%以下。又称熟铁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锻"},{"id":"glyph-kai-9540","script":"kai","character":"镀","reading":"dù","description":"利用化学、机械或电镀的方法使一种金属附着在别的金属或物体的表面上\n通过一种熔液涂上一层薄薄的金属\n用一层贵重金属覆盖表面\n镀 dù用电解或其他化学方法使一种金属的分子微粒附着到别的金属或物体表面，形成一层薄膜。\n【镀金】\n①在器物的表面镀上一薄层黄金。\n②讥讽一些人为取得虚名而到某个地方去做短期的锻炼或学习。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镀"},{"id":"glyph-kai-9547","script":"kai","character":"镇","reading":"zhèn","description":"安定～静。～定。\n军事上重要的地方边防重～。\n中国县以下的行政区划单位。\n较大的集市城～。村～。\n把饮料等同冰或冷水放在一起使凉冰～。\n时常十年～相随。\n中国明、清两代军队的编制单位。\n姓。\n⒈压，压制，慑住～尺。～纸。～压。～慑。～住。\n⒉安定～定。～静。～国家，抚百姓。\n⒊守住，用兵驻守～守。坐～。\n⒋较大的集市村～。乡～。市～。\n⒌将饮料等与冰或冷水放在一起使凉冰～汽水。\n⒍通\"整\"。整段时间，时常～日。～相随。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镇"},{"id":"glyph-kai-9550","script":"kai","character":"镐","reading":"gǎo","description":"镐头\n镐京。古都名。西周国都,在今陕西西安西南\n通皓”。光明的样子\n⒈一种刨土工具十字～。\n⒈镐京，西周的国都。在今陕西省长安之西北。\n⒉见gǎo。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镐"},{"id":"glyph-kai-9551","script":"kai","character":"镑","reading":"bàng","description":"镑张\n莫要镑张\n镑pāng 1.切削。 2.铲子的别名。\n镑bàng 1.英语pound的音译。英国﹑埃及﹑爱尔兰等国的本位货币。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镑"},{"id":"glyph-kai-955c","script":"kai","character":"镜","reading":"jìng","description":"其他光学用器\n⒈镜子，反映形象的器具。古用铜磨制，今用玻璃涂水银制成铜～。圆～子。穿衣～。〈喻〉取鉴的人或事以人为～。\n⒉使用光学原理制成的帮助视力或作科学实验等的器具眼～。放大～。电子显微～。天文望远～。三棱～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镜"},{"id":"glyph-kai-9570","script":"kai","character":"镰","reading":"lián","description":"锋利的棱角\n镰刀\n镰尾","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镰"},{"id":"glyph-kai-9576","script":"kai","character":"镶","reading":"xiāng","description":"铸铜铁器模型的瓤子\n古兵器名\n镶嵌物相嵌或相配合\n俗称修补其缺处\n如镶牙\n⒈将东西嵌进去或在外周加边～嵌。～牙。～金。～边。\n⒉马带上面的玉饰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镶"},{"id":"glyph-kai-957f","script":"kai","character":"长","reading":"cháng；zhǎng","description":"cháng：长度大，与短相对；时间久；长处。zhǎng：生长；年纪较大；负责人，如长者、校长。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-95e8","script":"kai","character":"门","reading":"mén","description":"房屋、围墙、车船\n⒈建筑物的进出口，设在进出口能开关的装置，泛指进出口前～。城～。洞～。飞机～。\n⒉形状或作用像门的炉～。球～。电～。\n⒊诀窍，途径，方法窍～。入～。找～路。\n⒋家，家族一～大小。双喜临～。灭～之祸。\n⒍分类～类。分～别类。\n⒏量词三～大炮。四～课程。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-门"},{"id":"glyph-kai-95ea","script":"kai","character":"闪","reading":"shǎn","description":"忽有忽无, 突然显现\n⒈天空的电光～电。〈引〉突然一亮～亮。灯光一～。\n⒉转侧身体躲避～开。躲～。\n⒊动作过猛或颠扑，以致扭伤～了脚。\n⒋光亮不定或晃动或忽明忽暗～动。～烁。～耀。\n⒌光辉耀眼，光芒四射～金光§星～ ～亮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闪"},{"id":"glyph-kai-95ed","script":"kai","character":"闭","reading":"bì","description":"泛指闭合,合拢\n①关；合～嘴、～眼。\n②堵住；阻塞不通～气、交通～塞。\n③停止；结束～幕、～会。\n④姓。\n【闭关锁国】闭关自守，不跟外国往来。\n【闭关自守】关闭关口，不跟外人往来。也比喻与外界隔绝，不接受外界事物的影响。\n【闭管式循环】血液始终在心脏和血管内按一定方向流动的循环方式。\n【闭果】干果的一类。果实成熟时，果皮失水干燥，但不开裂。瘦果、坚果、翅果等都属闭果。\n【闭合电路】电荷通过的整个电路。即从电源正极出发，经内、外电路又回到电源的正极的路径。又称全电路。\n【闭合电路欧姆定律】闭合电路中的电流强度跟电源的电动势成正比，跟内、外电路的电阻之和成反比。\n【闭合环流】大气运动在地面与高空形成的一个个闭合的大气活动中心。在海平面气压图上表现为永久性和半永久性活动中心，对流层中、上层则以西风环流为主要特点。\n【闭合系统】与外界有热和功交换而无质量交换的系统。\n【闭路电视】一种图像通信系统。其信号从源点只传给预先安排好的与源点相通的特定电视机。广泛用于大量不同类型的监视工作、教育、电视会议等。\n【闭门羹】拒绝客人进门叫做让客人吃闭门羹。也指找人时无人在家昨晚去找他，吃了个～。\n【闭门思过】关着门独自反省自己的过错。\n【闭门造车】关上门造车。比喻做事不考虑客观情况，脱离实际。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闭"},{"id":"glyph-kai-95ee","script":"kai","character":"问","reading":"wèn","description":"⒈不知的或不明白的请人解答请～。询～。去～明白。\n⒉审讯，查究，惩办～案。～罪。胁从不～。\n⒊管，追究，考察，干预过～。这件事你要亲自去～。\n⒋安慰，慰劳～候。慰～。\n①要求回答或解释的题目。\n②需要研究讨论或尚待解决之事遗留～题。\n③关键或重要之点～题所在。\n④事故或意外那辆汽车出～题了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-问"},{"id":"glyph-kai-95ef","script":"kai","character":"闯","reading":"chuǎng","description":"孟浪行事\n奔走谋生\n开辟\n①猛冲一头～进来、横冲直～。\n②经受实际的考验或锻炼经过几年的风风雨雨，他早～出来了。\n【闯荡】指离开故乡外出谋生～江湖。\n【闯江湖】旧时指奔走他乡，以算卦、表演杂耍、卖药治病等职业为生。\n【闯将】原指敢于冲锋陷阵的将领，后多用于非战争场合科学种田的～。\n⒈猛冲，敢干～入。～将。敢～。有股～劲。\n⒉奔走，浪游谋生，经历锻炼走南～北。～荡江湖。他～出了自己的路。\n⒊招惹～祸。～了乱子。\n闯chèn 1.出头貌。 2.探头观望。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闯"},{"id":"glyph-kai-95f0","script":"kai","character":"闰","reading":"rùn","description":"为协调历年与天文周期而增加的日或月，如闰日、闰月、闰年。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-95f2","script":"kai","character":"闲","reading":"xián","description":"马厩,关养马的地方\n伦理道德的规范、界限\n⒈没有事做空～。清～。～白了头。\n⒉放着，不使用～着。～置。\n⒋与正事无关～话。～人勿进。\n闲jiàn 1.空隙;缝隙。 2.指空子，可乘的机会。 3.嫌隙，隔阂。 4.阻隔;间隔。 5.差别;距离。 6.间杂，夹杂。 7.离间。 8.间谍。 9.伺候;侦伺。 10.私下\n闲jiān 1.中间;内。亦指事物两者的关系。 2.一定的空间或时间里。 3.一会儿;顷刻。 4.近来。 5.量词。房室单位。有时也指学校﹑工厂﹑商店等的单位。 6.量词\n。格﹑片﹑瓣。 7.量词。指动作次数。\n闲jiǎn 1.通\"简\"。检阅，视察。 2.通\"简\"。简省。 3.用同\"涧\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闲"},{"id":"glyph-kai-95f4","script":"kai","character":"间","reading":"jiān","description":"中间;内\n一会儿,顷刻\n⒈夹缝门～窥视。\n⒉当中，两种事物之中或相互的关系中～。两山之～。朋友之～。\n⒊一定的时期、地方或人群等范围时～。午～。地～。大人～。\n⒋房屋，屋子房～。洗澡～。\n⒌量词，多指房屋两～房子。三～店铺。安得广厦千万～。\n⒈空隙工作～隙。\n⒉隔开，不连结～隔。～断。〈引〉断断续续地时时而～进。\n⒊隔阂，疏远亲密无～。〈引〉离间赵王信秦之～。\n⒋更迭寒热～作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-间"},{"id":"glyph-kai-95f7","script":"kai","character":"闷","reading":"mèn","description":"气闷,因气不通畅而引起的不快之感\n沉默不出声或声音不响的样子\n密闭,使不透气\n呆在家里不出门\n过饱\n昏闷;失去知\n⒈气压低或空气不流通等引起的不舒服～气。～热。\n⒉不出门～在家里。\n⒊紧闭，不让出气刚泡的茶～一～再喝。\n⒋不出声或声音不响亮～声不响。～声～气。\n⒈心烦，不畅快烦～。～ ～不乐。\n⒉密封的～罐。～葫芦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闷"},{"id":"glyph-kai-95f8","script":"kai","character":"闸","reading":"zhá","description":"水闸\n制动器的通称\n电闸,在电路上用来接通、断开或转换电流的装置\n把水截住,关闸。引申为拦\n⒈拦阻水流的建筑物，可随时开关，调节水量～门。排洪～。\n⒉使机器减速或停运的制动器车～。电～。\n⒊铁路上的转辙器。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闸"},{"id":"glyph-kai-95f9","script":"kai","character":"闹","reading":"nào","description":"渐不喜闹\n热闹\n浓盛\n⒈人多声音杂乱～市。热～。\n⒉吵，喧哗，搅扰～翻了。～得可欢。无理取～。\n⒊戏耍，玩笑～着玩的。\n⒋发生～水灾。\n⒌发作～情绪。\n⒍干，搞，弄～春耕。～革新。～清情况。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闹"},{"id":"glyph-kai-95fa","script":"kai","character":"闺","reading":"guī","description":"内室\n⒈上圆下方的小门。\n⒉旧称女子居住的卧室或内室～房。深～。\n①未结婚的女子。\n②女儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闺"},{"id":"glyph-kai-95fb","script":"kai","character":"闻","reading":"wén","description":"⒈听耳～目睹。～过则喜。～风而起。\n⒉消息，听说的，听见的新～。奇～。～所未～。\n⒊出名，有名望～人。～名。\n⒍用鼻子嗅～着烟味。～到香味。\n闻wèn 1.声誉，名声。 2.通\"问\"。慰问。 3.通\"问\"。询问。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闻"},{"id":"glyph-kai-95fd","script":"kai","character":"闽","reading":"mǐn","description":"五代十国之一\n闽mǐn福建省的简称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闽"},{"id":"glyph-kai-9600","script":"kai","character":"阀","reading":"fá","description":"功劳\n名门巨室,仕宦人家\n依靠权势在某一方面有特殊支配地位的人物或集团\n阀门\n⒈〈古〉有权势有地位的家庭或家族名～之家。\n⒉〈古〉凭借权势、财力而拥有特殊地位的个人、家族或集团军～。财～。\n【阀阅】\n①〈古〉记载功绩或经历的簿籍。〈引〉功勋。\n②封建社会时代的贵族、官僚，大门外立两柱，左称\"阀\"，右称\"阅\"，用来张榜\"功状\"。因而又称他们为\"阀阅之家\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阀"},{"id":"glyph-kai-9601","script":"kai","character":"阁","reading":"gé","description":"门限\n一种架空的小楼房,中国传统建筑物的一种。其特点是通常四周设隔扇或栏杆回廊,供远眺、游憩、藏书和供佛之用\n⒈楼房的一种，一般两层，周围开窗，供游息、藏书等用亭台楼～。文渊～，在故宫。佛香～，在颐和园。\n⒉旧称女子的卧房闺～。\n⒊旧时宫中的政务机关，近代某些国家的最高行政机关内～。组～。～员。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阁"},{"id":"glyph-kai-9605","script":"kai","character":"阅","reading":"yuè","description":"引申为计算\n察看;视察,考查\n检阅\n⒈看～读。～览。传～。已～。\n⒉察看～兵。检～。\n⒊经历～历。～世。～年余。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阅"},{"id":"glyph-kai-960e","script":"kai","character":"阎","reading":"yán","description":"阎yán里巷的门，又指里巷～里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阎"},{"id":"glyph-kai-9610","script":"kai","character":"阐","reading":"chǎn","description":"开辟;开拓\n讲明白\n发扬,发展与提倡\n阐 chǎn说明；讲明白～明、～述。\n【阐明】讲明；说明文章～了物体运动的规律。\n【阐扬】说明并宣扬～我国的对外政策。\n⒈说明，表明～明。～发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阐"},{"id":"glyph-kai-9614","script":"kai","character":"阔","reading":"kuò","description":"宽横的距离大\n有江千里阔。╠\n⒈宽广宽～。广～。辽～〓～三十里。〈引〉时间或距离长～别五十年。\n⒉疏略，不切实～略。迂～。\n⒊宽缓，放宽～其租赋。\n⒋富有的，奢侈的～人。～气。～绰。摆～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阔"},{"id":"glyph-kai-961f","script":"kai","character":"队","reading":"duì","description":"坠落\n队列\n军队或集体的编制单位\n①行列排～、整～。\n②集体的编制单位生产～、球～。\n③特指少年先锋队～旗。\n④量词。\n【队礼】中国少年先锋队队员行的礼。右手五指并拢，手掌向前，高举头上，表示人民利益高于一切。\n【队日】少年先锋队举行集体活动的日子，除假期外一般每周一次。\n队zhuì 1.坠落◇作\"坠\"。 2.指倒翻。 3.引申为低沉。 4.殒灭;丧失。\n队suì 1.隧道。 2.泛指道路。 3.特指险道﹑要道。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-队"},{"id":"glyph-kai-9632","script":"kai","character":"防","reading":"fáng","description":"fáng：(1)戒备，预先作好应急的准备～止。～备。预～。～范（防备，戒备）。～患未然。～意如城（指严格控制个人欲望，就像守城防敌一样）。～微杜渐（在坏事和错误刚冒头的时候就加以制止，以免发展下去）。\n(2)守卫～守。边～。～。\n(3)堤坝～堤。以～止水”。\n(4)抵得，相当百夫之～（抵得上百人的人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-防"},{"id":"glyph-kai-9633","script":"kai","character":"阳","reading":"yáng","description":"泰山之阳,汶水西流。\n⒈跟\"阴\"相对。〈古〉我国哲学家把一切事物概括为\"阴阳\"两个对立统一的范畴火为～，水为阴。背为～，胸为阴。胸为～，腹为阴。\n⒉指太阳～光。向～花。\n⒊明亮，温暖多～。\n⒋凸出的，外露的～文。～沟。～奉阴违。\n⒌带正电的～电。～极。\n⒎迷信者所谓\"属于活人与人世\"的～寿。～间。\n⒏男性生殖器～物。\n①显露出来的化验～性。\n②雄性，男性的。\n⒑〈古〉通\"佯\"。假装。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阳"},{"id":"glyph-kai-9634","script":"kai","character":"阴","reading":"yīn","description":"阴谷皆入济\n以胸腹而言，胸在上为阳，腹在下为～。以阴阳交错的变化，说明物质世界的运动和发展。\n⒉称月亮为\"太阴\"，简称\"阴\"月为～。～历。\n⒋云遮挡着太阳或月亮、星星～天。夕～。～雨。\n⒌光线被东西遮住所造成的影子～影。树～。\n⒍山的北面，水的南面居山之～『水之～。华～县，在陕西省华山之北。江～县，在江苏省长江之南。\n⒎带负电的～电。～极。\n⒏物体的背面碑～。\n⒐诡诈，不光明正大～谋诡计。～险毒辣。\n⒑女的，雌的或化验用语男为阳，女为～。～性反应。\n⒒生殖器或专指女性生殖器女～。\n⒓迷信者所谓\"属于鬼、神的\"～间、～宅等等都是虚构的。\n①天气低沉郁闷。\n②气氛不活跃。\n③忧郁、不开朗～郁不乐。\n阴yìn 1.覆荫;庇护。 2.埋藏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阴"},{"id":"glyph-kai-9635","script":"kai","character":"阵","reading":"zhèn","description":"军队作战时布置的局势～线。～势。严～以待。\n战场～地。～亡。冲锋陷～。\n量词，指事情或动作经过的段落～发。～痛。下了一～雨。\n⒉量词。〈表〉事情或动作经过的段落一～掌声。一～风雷雨。又指时间这～子太忙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阵"},{"id":"glyph-kai-9636","script":"kai","character":"阶","reading":"jiē","description":"梯子\n⒉〈古〉官员的品级官～。\n①指同一阶级中因经济地位的不同而分成的层次农民阶级中有富农、中农、贫农等～层。\n②指由不同阶级出身，而因某种相同的特征所形成的集团知识分子～层。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阶"},{"id":"glyph-kai-963b","script":"kai","character":"阻","reading":"zǔ","description":"zǔ：(1)险要的地方马陵道狭，而旁多～隘，可伏兵”。\n(2)拦挡～挡。～隔。～拦。～力。～挠。梗～。劝～。～击。～抑。～滞。～难（nàn）。～塞（sè）。\n(3)艰难道～且长。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阻"},{"id":"glyph-kai-963f","script":"kai","character":"阿","reading":"ā","description":"ā：加在称呼上的词头～大。～爷。～爹。～罗汉。～毛。～婆。～弟。～姊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阿"},{"id":"glyph-kai-9644","script":"kai","character":"附","reading":"fù","description":"fù：(1)另外加上，随带着～体。～件。～带（ａ．另外有所补充的；ｂ．非主要的）。～庸。～会（ａ．把不相关连的事勉强拉到一起，如牵强～～”；ｂ．组织文章、布局谋篇、命意修辞等创作活动，如精思～～，十年乃成”）。～赘悬疣。\n(2)同意，赞同随声～和。～议。\n(3)捎带一男～书至”。\n(4)靠近～近。～耳低言。\n(5)依从依～。归～。趋炎～势。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-附"},{"id":"glyph-kai-9645","script":"kai","character":"际","reading":"jì","description":"泛指合缝的地方;缝隙\n边缘\n时候;时机\n去就之际\n⒈交界处，边缘处海～。天～。一望无～。\n⒉彼此之间省～。国～。厂～竞争。\n⒊时候或先后交接的时候胜利之～。夏秋之～。\n⒋当，适逢～此美景。\n⒌会合，交流刚柔～也。广泛交～。\n⒍到，接近～天接地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-际"},{"id":"glyph-kai-9646","script":"kai","character":"陆","reading":"lù；liu","description":"数目字六”的大写\n水陆并进。\n路;道\n⒈\"六\"的大写。\n⒈高出水面的土地～地。～路。登～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陆"},{"id":"glyph-kai-9648","script":"kai","character":"陈","reading":"chén","description":"古国名\n陈朝\n战阵;行列\n陈设,陈列","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陈"},{"id":"glyph-kai-964b","script":"kai","character":"陋","reading":"lòu","description":"lòu：(1)丑的，粗劣，不文明的丑～。粗～。～俗。\n(2)狭小，简略～室。简～。因～就简。～巷簟瓢（形容家境贫寒，生活清苦）。\n(3)见识小浅～。孤～寡闻。\n(4)轻视～今而荣古。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陋"},{"id":"glyph-kai-964c","script":"kai","character":"陌","reading":"mò","description":"mò：(1)田间东西方向的道路，泛指田间小路阡～。～上。～头（路边）。～路（ａ．田间道路；ｂ．指路上相见而不认识的人，如视同～～”）。\n(2)生疏，不熟悉～生。\n(3)市中街道街～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陌"},{"id":"glyph-kai-964d","script":"kai","character":"降","reading":"jiàng","description":"jiàng：(1)下落，落下下～。～旨。～临。～旗。空～。\n(2)减低，贬抑～低。～价。～职。～解（jiě）。～心相从（抵制自己心志以服从别人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-降"},{"id":"glyph-kai-9650","script":"kai","character":"限","reading":"xiàn","description":"xiàn：(1)指定的范围期～。界～。权～。局～。～额。\n(2)指定范围～制。～于。～期。～价（官方指定最高或最低价格，不得超越）。无～。\n(3)门槛门～。\n(4)险阻关～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-限"},{"id":"glyph-kai-9655","script":"kai","character":"陕","reading":"shǎn","description":"古地名。战国陕邑,在今河南省陕县\n中国陕西省的简称\n狭窄","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陕"},{"id":"glyph-kai-9661","script":"kai","character":"陡","reading":"dǒu","description":"dǒu：(1)斜度很大，近于垂直～坡。～峭。～立。～峻。\n(2)突然～然。～变。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陡"},{"id":"glyph-kai-9662","script":"kai","character":"院","reading":"yuàn","description":"yuàn：(1)围墙里房屋四周的空地～子。～墙。庭～。\n(2)某些机关、学型公共场所名称法～。医～。戏～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-院"},{"id":"glyph-kai-9664","script":"kai","character":"除","reading":"chú","description":"chú：(1)去掉～害。～名。～根。铲～。废～。排～。～暴安良。\n(2)改变，变换岁～（农历一年的最后一天）。～夕。\n(3)不计算在内～非。～外。\n(4)算术中用一个数去分另一个数，是乘”的反运算～法。\n(5)台阶阶～。庭～。\n(6)任命官职～拜（授官）。～授。～书（授官的诏令）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-除"},{"id":"glyph-kai-9668","script":"kai","character":"陨","reading":"yǔn","description":"丧失,失去\n天诱其衷,成王陨命,穆公是以不\n陨yǔn从高处掉下，坠落～石。～星。\n陨yuán 1.周围;幅员。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陨"},{"id":"glyph-kai-9669","script":"kai","character":"险","reading":"xiǎn","description":"常石险远。\n地势险峻、危险\n⒈地势扼要，难于通过～要。～阻。天～。\n⒉地势不平坦～以远，则至者少。\n⒊危，不安全危～。冒～∶～。～症。～境。\n⒋狡诈，狠毒～诈。～恶。～毒。阴～。\n⒌几乎，差一点～遭暗算。～些丧命。\n险jiǎn 1.少。\n险yán 1.岩岸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-险"},{"id":"glyph-kai-966a","script":"kai","character":"陪","reading":"péi","description":"péi：(1)跟随在一起，在旁边做伴～伴。～同。～客。～葬。～嫁。失～。\n(2)从旁协助，辅佐～臣。～审。\n(3)增加的，非主要的～衬。～都。\n(4)古同赔”，偿还。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陪"},{"id":"glyph-kai-9675","script":"kai","character":"陵","reading":"líng","description":"líng：(1)大土山山～。丘～。～谷迁变（简作陵谷”）。\n(2)高大的坟墓～园。～墓。～寝。\n(3)古同凌”，侵犯，欺侮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陵"},{"id":"glyph-kai-9676","script":"kai","character":"陶","reading":"táo","description":"táo：(1)用黏土烧制的器物～俑。～粒。～瓷。～管。～器。\n(2)制造陶器～冶。～铸。\n(3)喻教育、培养～化。～育。～染。熏～。\n(4)快乐的样子，使快乐～然。～醉。～～。\n(5)古同淘”，洗。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陶"},{"id":"glyph-kai-9677","script":"kai","character":"陷","reading":"xiàn","description":"xiàn：(1)掉进，坠入，沉下～落。～没（mò）。～溺。～于。～入。\n(2)为捉野兽挖的坑～坑。～阱。\n(3)凹进双眼深～。\n(4)设计害人～害。诬～。～人于罪。\n(5)攻破，占领失～。沦～。\n(6)缺点缺～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陷"},{"id":"glyph-kai-9685","script":"kai","character":"隅","reading":"yú","description":"yú：(1)角落城～。墙～。屋～。～隙（屋角的洞穴）。向～而泣。\n(2)靠边的地方海～。\n〔～中〕将近中午的时候。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隅"},{"id":"glyph-kai-9686","script":"kai","character":"隆","reading":"lóng","description":"lóng：(1)盛大，厚，程度深～冬。～重（zhòng）。\n(2)兴（xīng）盛兴～。～盛（shèng）。\n(3)高，高起～起。～穹。～准（高鼻梁）。\n(4)尊崇～师。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隆"},{"id":"glyph-kai-968b","script":"kai","character":"隋","reading":"suí；duò","description":"suí：(1)中国朝代名～代。\n(2)姓。\nduò：(1)古代祭祀用的残肉和残食既祭，则藏其～”。\n(2)古同堕”，垂落。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隋"},{"id":"glyph-kai-968f","script":"kai","character":"随","reading":"suí","description":"⒈跟着，沿着，顺着～着。跟～。～波逐流。\n⒉顺从，任凭～意。～你的便。～遇而安。～心所欲。\n⒊顺便，顺手～手关灯。\n⒋即，立刻～即。～叫～到。\n①顺从附和别人的意见～和大伙意见。\n②指态度和气，不固执己见他一向很～和。\n随tuǒ 1.椭圆貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-随"},{"id":"glyph-kai-9690","script":"kai","character":"隐","reading":"yǐn","description":"藏匿;隐蔽\n则事可以隐定。\n⒈藏匿，潜伏，不显露～藏。～匿。～伏。～居。～患。\n⒉不明显，不清楚～痛。～约其辞。\n⒊不说出来，不让人知道～讳。～情。～瞒。\n隐yìn 1.依据;凭依。 2.筑，击。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隐"},{"id":"glyph-kai-9694","script":"kai","character":"隔","reading":"gé","description":"gé：(1)遮断～开。～离。～绝。～断。阻～。\n(2)相去有一段距离～壁。～年。～行（háng）。～岸观火（喻见人遇到困难，漠不关心，采取观望或看热闹的态度）。～墙有耳。\n(3)思想感情有距离～阂。～膜。～心。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隔"},{"id":"glyph-kai-9698","script":"kai","character":"隘","reading":"ài","description":"ài：(1)险要的地方～口。要～。关～。险～。\n(2)狭窄～巷。～路。狭～。\n(3)穷～穷。～窘。贫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隘"},{"id":"glyph-kai-9699","script":"kai","character":"隙","reading":"xì","description":"xì：(1)裂缝～罅（裂缝）。缝～。～大而墙坏。\n(2)感情上的裂痕～嫌。有～。仇～。\n(3)闲，空～地（空地）。农～。\n(4)机会，空子乘～。\n(5)际，接近北～乌丸、夫馀”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隙"},{"id":"glyph-kai-969c","script":"kai","character":"障","reading":"zhàng","description":"zhàng：(1)阻隔，遮挡～蔽。～翳。～碍。故～。～眼法。一叶～目，不见泰山。\n(2)中国秦、汉两代边塞上作防御用的城堡出五原塞数百里，远者千里，筑城～列亭，至庐朐”。\n(3)用作遮蔽、防卫的东西屏～。\n(4)古同幛”，画轴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-障"},{"id":"glyph-kai-96a7","script":"kai","character":"隧","reading":"suì","description":"suì：(1)道路，特指门内当中的路。\n(2)郊外的地方鲁人三郊三～”。\n(3)古同燧”，边塞设置的守望烽火的亭子。\n(4)旋转若磨石之～”。\n〔～道〕在山中或地下凿成的通路。亦称隧洞”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隧"},{"id":"glyph-kai-96b6","script":"kai","character":"隶","reading":"lì","description":"跟从;附属\n通离”。流离\n通肄”\n检查\n练习\n⒈附属，属于～属。直～中央。\n⒉封建时代的衙役、差役～卒。皂～。\n⒊旧时地位低、被奴役的人奴～。仆～。\n⒋一种汉字字体，相传是秦朝程邈所创造～书。\n隶dài 1.及;捕获◇作\"逮\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隶"},{"id":"glyph-kai-96be","script":"kai","character":"难","reading":"nán；nàn","description":"nán：不容易，困难；使人为难。nàn：灾难，祸患；责难。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-96c0","script":"kai","character":"雀","reading":"què；qiāo；qiǎo","description":"què：鸟类的一科，吃粮食镣昆虫。特指麻雀”，泛指小鸟～跃（高兴得像雀儿那样跳跃）。～盲（即夜盲症”）。～斑。～噪（名声宣扬，含贬义）。\nqiāo：〔～子〕即雀斑”。\nqiǎo：义同（一），用于一些口语词～盲眼（即雀（què）盲”）。家～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雀"},{"id":"glyph-kai-96c1","script":"kai","character":"雁","reading":"yàn","description":"yàn：鸟类的一属，形状略像鹅，群居水边，飞时排列成行～行（háng）。～序。～阵（雁行整齐，如同军队布阵）。～过拔毛（喻为牟利不放过任何机会）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雁"},{"id":"glyph-kai-96c4","script":"kai","character":"雄","reading":"xióng","description":"xióng：(1)阳性的，与雌”相对～性。～鸡。～狮。～蕊。～蜂。\n(2)强有力的～壮。～健。～伟。～厚。～浑。～劲。～奇。～踞。～视。～姿。～心。～关。～图。～辩。～才大略。\n(3)强有力的人或国家～杰（ａ．才能出众的人；ｂ．才能出众）。～俊。英～。枭～。奸～。称～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雄"},{"id":"glyph-kai-96c5","script":"kai","character":"雅","reading":"yǎ","description":"yǎ：(1)正规的，标准的～言。～正（ａ．规范的；ｂ．正直；ｃ．客气话，用于赠给他人的书画题款上，请对方指正）。\n(2)美好的，高尚的，不粗俗的文～。高～。典～。～观。～教（jiào）。～兴（xìng）。～座。～俗。\n(3)平素，素来～爱。～善鼓琴。\n(4)极，甚～以为美。～不欲为。\n(5)交往无一日之～。\n(6)酒器名～量（liàng）（ａ．大的酒量；ｂ．宽宏的气度）。\n(7)中国周代朝庭上的乐歌风～颂。～声（泛指诗歌）。\n(8)古同鸦”，乌鸦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雅"},{"id":"glyph-kai-96c6","script":"kai","character":"集","reading":"jí","description":"jí：(1)群鸟栖止于树上黄鸟于飞，～于灌木”。\n(2)聚合，会合聚～。～合。～会。～体。～团。～训。～散。～资。～中。～大成。～腋成裘。\n(3)会合许多著作编成的书～子。文～。诗～。选～。全～。\n(4)大型图书中可以相对独立的一部分，或一部小说、一部电影、电视剧中相对独立的段落上～。第五～。\n(5)定期交易的市场～市。赶～。\n(6)中国古代图书的四部分类法～部。经史子～。\n(7)成就，成功大业未～。\n(8)数学基本概念之一，指若干具有共同属性的事物的总体子～。交～。\n(9)古同辑”，和睦。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-集"},{"id":"glyph-kai-96c7","script":"kai","character":"雇","reading":"gù","description":"gù：(1)出钱让人为自己做事～工。～主。～用。～员。～佣。～请。\n(2)租赁交通运输工具～车。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雇"},{"id":"glyph-kai-96cc","script":"kai","character":"雌","reading":"cí","description":"cí：(1)母的，阴性的，与雄”相对～性。～花。～雄。\n(2)柔羽。\n〔～黄〕矿物，橙黄色，可做颜料，古时用来涂改文字，如信口～～”（随意讥评）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雌"},{"id":"glyph-kai-96cf","script":"kai","character":"雏","reading":"chú","description":"引申为幼禽\n幼小的动物\n幼儿\n【雏形】\n①初步形成的规模。\n②照原形缩小后的模型。\n雏jù 1.人名用字。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雏"},{"id":"glyph-kai-96d5","script":"kai","character":"雕","reading":"diāo","description":"diāo：(1)鸟类的一属，大型猛禽，羽毛褐色，上嘴勾曲，视力很强，利爪，能捕食山羊、野兔等（亦作鹫”）～悍。一箭双～。\n(2)刻竹、木、玉、石、金属等木～。浮～。玉～。～版。～龙（指善于撰写文章）。～镌。～塑。～虫小技。\n(3)有彩绘装饰的～弓。～鞍。～青（在人体上刺花纹，涂上青色）。\n(4)同凋”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雕"},{"id":"glyph-kai-96e8","script":"kai","character":"雨","reading":"yǔ","description":"从云中落向地面的水滴。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"}];
